export const BUILTIN_SPECS: Record<string, { spec: string; template?: string; example?: string }> = {
  "design": {
    "spec": "# .dsh/file-format-specs/design/spec.yaml —— 设计文档（Design Doc）格式规范\n# 结构取自四条主线的交集：\n#   Google  ：Context & Scope → Goals / Non-Goals → Alternatives → Cross-Cutting → Open Questions\n#   Amazon  ：从客户倒推 + 内部 FAQ（最坏情况 / 怎么退 / 谁被叫起来）+ 不可逆动作单独标出\n#   Cagan   ：四风险（价值 / 可用性 / 可行性 / 商业可行性）必须给证据，价值未验证不许开工\n#   Wiegers ：设计要对得上需求（需求来源 + 追溯）+ 接口是可验证的契约 + 章节级 serves 标注\next: md\npriority: 80\n# 文件名定不了就用路径约束：任意 **/design/**/*.md（只有 match_path 也可以）\nmatch_path:\n  - \"**/design/**/*.md\"\nmode: block\ndiff_mode: delta\nmax_attempts: 3\non_exhausted: allow\n\n# —— 规则引擎 ——\nderive:\n  - fact: interfaceCount          # 全文数 IF-1 这类编号（含表格单元格）\n    fn: countIds\n    args: [[\"IF\"]]\n\nfunctions:\n  hasOwner:\n    expr: \"!!(frontmatter.owner || frontmatter.owner_team)\"\n\n  noPlaceholder:\n    expr: \"!/TODO|TBD|待补充/.test(text)\"\n\n  # 动态函数 2：script 自定义函数（返回违规列表）\n  # 上下文：doc / text / fileName / relPath / api（hasSection / section / collectIds / frontmatter / violation）\n  # 每个 H2 都要带 serves 标注：指向它服务的需求编号（FR-x / NFR-x），全文性章节写「全文」。\n  # 只查 H2——结构契约的层级是 H2；H3 是节内小节，H4 是编号实例（IF-1），不在此列。\n  everySectionServes:\n    script: |\n      return doc.headings\n        .filter(h => h.level === 2 && !/serves\\s*[:：]/i.test(h.text))\n        .map(h => ({ message: '章节「' + h.text + '」缺 serves 标注', line: h.line, key: 'serves:' + h.line }))\n\nrules:\n  - id: fm\n    assert:\n      fn: frontmatterRequired\n      args:\n        - keys: [title, status]\n  - id: status-enum\n    assert: { fn: frontmatterEnum, args: [{ key: status, values: [draft, review, approved, superseded] }] }\n\n  # 必备章节，按评审顺序（结构节只认 H2）\n  - id: sections\n    assert:\n      fn: sectionsRequired\n      args:\n        - order: true\n          headings:\n            - 摘要\n            - 背景与问题\n            - 目标与非目标\n            - 方案总览\n            - 架构与依赖\n            - 数据模型\n            - 接口设计\n            - 备选方案\n            - 四风险与证据\n            - 失败模式与回滚\n            - 跨关注点\n            - 交付拆分与里程碑\n            - 需求追溯\n            - 常见问题\n            - 开放问题\n            - 附录\n\n  # 关键表格：缺表 / 缺列 / 行数不足都会被打回\n  # 需求来源：Amazon「从客户倒推」+ Wiegers 的需求出处\n  - id: origin-table\n    assert: { fn: tableRequired, args: [{ under: 背景与问题, header: [需求编号, 原始诉求, 本设计如何回应] }] }\n  # 接口契约：清单给全貌，明细给语义（错误码与兼容性必填，由 interface-details 判）\n  - id: interface-table\n    assert: { fn: tableRequired, args: [{ under: 接口设计, header: [编号, 接口, 输入, 输出, 失败与错误, 兼容性] }] }\n  - id: interface-details\n    assert: { fn: idDetails, args: [{ under: 接口设计, fields: [语义, 错误码, 兼容性], optional: [幂等与重试] }] }\n  # 备选方案：Google Alternatives——至少两个，其中一个必须是「什么都不做」\n  - id: option-table\n    assert: { fn: tableRequired, args: [{ under: 备选方案, header: [方案, 一句话说明, 优点, 代价, 为什么未选], min_rows: 2 }] }\n  # 四风险：Cagan 价值 / 可用性 / 可行性 / 商业可行性，每项都要有证据\n  - id: risk-table\n    assert: { fn: tableRequired, args: [{ under: 四风险与证据, header: [风险类型, 判断问题, 现有证据, 结论], min_rows: 4 }] }\n  # 失败与回滚：没有回滚方案不许开工\n  - id: failure-table\n    assert: { fn: tableRequired, args: [{ under: 失败模式与回滚, header: [失败场景, 触发条件, 用户可见影响, 检测手段, 回滚动作, 决策人] }] }\n  # 跨关注点：Google Cross-Cutting，逐项给结论，不许留空\n  - id: crosscut-table\n    assert: { fn: tableRequired, args: [{ under: 跨关注点, header: [关注点, 结论, 依据与措施] }] }\n  - id: milestone-table\n    assert: { fn: tableRequired, args: [{ under: 交付拆分与里程碑, header: [里程碑, 内容, 出口判据, 负责人, 目标日期] }] }\n  # 需求追溯：Wiegers——设计节 ↔ 需求 ↔ 测试 ↔ 指标\n  - id: trace-table\n    assert: { fn: tableRequired, args: [{ under: 需求追溯, header: [需求编号, 设计节, 测试用例, 指标] }] }\n  # 内部 FAQ：Amazon 的刻薄问题，少于 6 条说明没认真想\n  - id: faq-table\n    assert: { fn: tableRequired, args: [{ under: 常见问题, header: [问题, 回答], min_rows: 6 }] }\n  - id: open-questions\n    assert: { fn: tableRequired, args: [{ under: 开放问题, header: [问题, 选项, 负责人, 截止] }] }\n\n  - id: has-owner\n    when: { path: \"frontmatter.status\", op: \"notEmpty\" }   # 守卫：只对有 status 的文档生效\n    assert: { fn: \"hasOwner\", message: \"设计文档必须有 owner 或 owner_team\" }\n    priority: 10\n\n  - id: at-least-one-interface\n    assert: { path: \"interfaceCount\", op: \"gte\", value: 1, message: \"接口设计至少一条编号（IF-1…）：设计必须有可评审的契约\" }\n\n  - id: no-placeholder\n    severity: warning\n    assert: { fn: noPlaceholder, message: \"文档里不能留 TODO / TBD / 待补充\" }\n\n  - id: every-section-serves\n    assert: { fn: everySectionServes }\n",
    "template": "---\ntitle: <设计标题>\nstatus: draft\nowner: <设计负责人 / DRI>\nreviewers: <评审人>\nprd: <关联 PRD 路径>\nserves: <覆盖的需求编号，如 FR-1、FR-3>\ncreated: <YYYY-MM-DD>\nupdated: <YYYY-MM-DD>\n---\n\n# <设计标题>  serves: <FR-1>\n\n（说明：本文是 Design Review 的**评审对象**。PRD 回答「做什么、为什么值得做」，本文只回答「怎么做、为什么这么做、坏了怎么退」。PRD 的内容只放链接与编号，**不复述**——复述必然与 PRD 分叉。每个 `##` 标题都要带 `serves:` 标注：指向它服务的需求（`FR-x` / `NFR-x`），全文性章节写「全文」。）\n\n## 摘要  serves: 全文\n\n（说明：3 行以内回答三问——解决什么问题 / 方案一句话 / 影响面多大。细节留给后面各节，这里只给读者一张地图。）\n\n- **问题**：<一句话说清要解决什么>\n- **方案**：<一句话说清怎么做，不写技术栈罗列>\n- **影响面**：<新增 / 修改的模块、接口、数据；谁要配合、谁会被改到>\n\n## 背景与问题  serves: 全文\n\n（说明：Amazon 的「从客户倒推」——先讲谁在受苦、今天怎么凑合、代价多大，再讲为什么现在做。用数据或原话，不要写「用户很痛苦」。）\n\n### 需求来源\n\n（说明：Wiegers 的可追溯起点——设计不是凭空来的，逐条写清本设计在回应哪条需求、原始诉求是什么、有没有被改写。）\n\n| 需求编号 | 原始诉求 | 本设计如何回应 |\n|---|---|---|\n| <FR-1> | <谁提的 / 工单号 / 原话> | <设计上怎么满足（一句话）> |\n\n### 现状与代价\n\n（说明：今天用户或系统是怎么做的？具体到步骤与耗时，替代做法是什么；给出处（访谈 / 工单 / 监控数据）。）\n\n### 为什么是现在\n\n（说明：不做会怎样？代价随时间怎么变化？触发条件是什么？）\n\n## 目标与非目标  serves: 全文\n\n（说明：Google 的 Goals & Non-Goals。目标要可判定——能被测试或数据证伪，不写「提升体验」这类词；**非目标至少 3 条**，写不出非目标说明范围还没想清，本评审不应开始。）\n\n### 目标\n\n- <目标（可判定）>\n\n### 非目标\n\n- <本次明确不做的事 + 为什么不做（做了要付出什么）>\n\n## 方案总览  serves: <FR-1>\n\n（说明：一段话讲清方案，让不熟悉背景的人也能读懂；再给一张系统上下文或时序图。图只表达结构，正文必须能独立读懂。）\n\n**一句话方案**：<...>\n\n```text\n<调用方> --> <入口> --> <核心模块> --> <存储 / 外部依赖>\n```\n\n**关键概念**：<本设计引入的新名词 + 一句话定义；没有就写「无新增概念」>\n\n## 架构与依赖  serves: <FR-1>\n\n（说明：模块怎么切、依赖方向朝哪、为什么这么切。写清新增或变更的依赖，以及依赖不可用时的行为。）\n\n- **模块划分**：<模块 → 职责>\n- **依赖方向**：<谁调谁、有没有环、为什么这样切>\n- **外部依赖**：<新增 / 变更的依赖 + 它挂掉时的降级行为>\n- **与既有架构的差异**：<这次偏离了什么约定；无则写「无」>\n\n## 数据模型  serves: <FR-2>\n\n（说明：实体、字段、约束、生命周期。涉及存量数据时，迁移、回填、兼容与删除策略必须写；不涉及数据变更就写「不适用：<理由>」。）\n\n- **实体与字段**：<实体 → 关键字段与类型>\n- **约束与不变量**：<唯一性、外键、状态机约束>\n- **迁移与回填**：<表结构变更、回填顺序、双写与对账、能否回滚>\n- **生命周期**：<写入 → 更新 → 归档 / 删除；留存期限>\n\n## 接口设计  serves: <FR-3>\n\n（说明：接口是**契约**。清单给全貌，明细给语义——**错误码与兼容性是必填项**。字段类型、方法签名这类机器可读的部分以 proto / OpenAPI / 类型定义为准，本文只写它们表达不了的语义（有意行为、失败语义、版本承诺）；面向使用者的用法说明另见用户文档。）\n\n| 编号 | 接口 | 输入 | 输出 | 失败与错误 | 兼容性 |\n|---|---|---|---|---|---|\n| IF-1 | <方法 / 端点 / 事件 / 配置项> | <入参以及非法值> | <返回值或副作用> | <失败情形 → 错误码> | <版本策略 / 兼容承诺> |\n| IF-2 | <...> | <...> | <...> | <...> | <...> |\n\n#### IF-1 <接口名>\n\n**语义**\n\n<做什么、边界在哪、调用方该怎么用；不要复述参数表。>\n\n**错误码**\n\n<失败情形 → 错误码 → 调用方应如何处理（重试 / 放弃 / 降级）。>\n\n**兼容性**\n\n<是否破坏性变更、版本与废弃时间表、旧调用方怎么办。>\n\n**幂等与重试**（需要时才写；不需要就删掉这块）\n\n<同一请求重复执行的结果；重试键与退避策略。>\n\n#### IF-2 <接口名>\n\n**语义**\n\n<...>\n\n**错误码**\n\n<...>\n\n**兼容性**\n\n<...>\n\n## 备选方案  serves: 全文\n\n（说明：Google 的 Alternatives Considered。至少两个方案，其中一个必须是「什么都不做」；「为什么未选」要写代价，不许写「过于复杂」。）\n\n| 方案 | 一句话说明 | 优点 | 代价 | 为什么未选 |\n|---|---|---|---|---|\n| A（选用） | <...> | <...> | <...> | — |\n| B | <...> | <...> | <...> | <写清代价，不写「过于复杂」> |\n| C：什么都不做 | 维持现状 | <...> | <...> | <现在为什么不能接受> |\n\n## 四风险与证据  serves: 全文\n\n（说明：Cagan 的四项风险。**这一节写证据，不写判断**——没有证据就写「未验证」。价值风险未验证时，评审结论不得为「通过」，只能先做最便宜的验证。）\n\n| 风险类型 | 判断问题 | 现有证据 | 结论 |\n|---|---|---|---|\n| 价值 | 用户真的想要吗 | <访谈 / 原型测试 / 数据；无则写「无」> | 已验证 / 部分 / 未验证 |\n| 可用性 | 用户会用吗 | <可点击原型 / 任务测试 / 同类功能完成率> | 已验证 / 部分 / 未验证 |\n| 可行性 | 我们建得出来吗 | <技术验证 / 压测 / 同类实现 / 原型代码> | 已验证 / 部分 / 未验证 |\n| 商业可行性 | 公司能接受吗 | <成本测算 / 合规确认 / 渠道与定价> | 已验证 / 部分 / 未验证 |\n\n**未验证项的补课计划**：<哪项未验证 → 用最便宜的方式怎么证伪 → 谁 → 什么时候要结论>\n\n## 失败模式与回滚  serves: 全文\n\n（说明：Amazon 内部 FAQ 的核心——最坏会怎样、怎么发现、怎么退回来。**没有回滚方案的设计不许开工**；不可逆的动作要单独标出来。）\n\n| 失败场景 | 触发条件 | 用户可见影响 | 检测手段 | 回滚动作 | 决策人 |\n|---|---|---|---|---|---|\n| <...> | <...> | <...> | <指标 / 告警 / 日志> | <关开关 / 回滚版本 / 限流 / 人工修数> | <谁> |\n\n- **开关**：<名称、默认值、粒度（全局 / 租户 / 用户）>\n- **回滚演练**：<什么时候演练、谁做、预期多久恢复>\n- **不可逆动作**：<一旦执行无法撤销的操作 + 事前保护；没有就写「无」>\n\n## 跨关注点  serves: 全文\n\n（说明：Google 的 Cross-Cutting Concerns——逐项给结论；不适用的写「不适用：<理由>」，不要留空。）\n\n| 关注点 | 结论 | 依据与措施 |\n|---|---|---|\n| 安全 | <结论> | <鉴权、越权、注入、密钥管理> |\n| 隐私与合规 | <结论> | <采集什么、存多久、谁能看、能否删除> |\n| 成本 | <结论> | <新增资源与量级；最坏情况> |\n| 可观测性 | <结论> | <日志 / 指标 / 追踪 / 告警阈值与接收人> |\n| 性能与容量 | <结论> | <压测结论或估算口径；先坏在哪里> |\n| 文档与支持 | <结论> | <用户文档、帮助中心、值班手册谁写> |\n\n## 交付拆分与里程碑  serves: 全文\n\n（说明：拆分要能各自独立验证；每个里程碑给**出口判据**，别写「完成开发」。契约冻结点要显式标出。）\n\n| 里程碑 | 内容 | 出口判据 | 负责人 | 目标日期 |\n|---|---|---|---|---|\n| M1 | <骨架 + 接口> | <契约冻结 / 可联调> | <谁> | <日期> |\n| M2 | <主流程 + 埋点> | <埋点验收通过> | <谁> | <日期> |\n| M3 | <灰度 → 全量> | <指标达标 / 无 P0·P1> | <谁> | <日期> |\n\n## 需求追溯  serves: 全文\n\n（说明：Wiegers 的追溯——每个设计实体节都要能对上需求，每条需求都要有测试与指标落点。对不上的，要么需求该删，要么设计漏了。）\n\n| 需求编号 | 设计节 | 测试用例 | 指标 |\n|---|---|---|---|\n| <FR-1> | <架构与依赖 / 接口设计> | <用例编号 / 无> | <指标编号 M-x / 不适用> |\n\n## 常见问题  serves: 全文\n\n（说明：Amazon 的内部 FAQ——问题要刻薄，答案要短。至少 6 问：最可能被投诉什么、6 个月后成为什么负担、流量涨 10 倍先坏在哪、谁半夜被叫起来、数据错了怎么修、这个决定错了多久能发现。）\n\n| 问题 | 回答 |\n|---|---|\n| <最可能被投诉什么> | <...> |\n| <6 个月后会成为什么负担> | <...> |\n| <流量涨 10 倍先坏在哪里> | <...> |\n| <谁半夜被叫起来、手上有什么> | <...> |\n| <数据错了怎么修、修得回来吗> | <...> |\n| <这个决定错了多久能发现> | <...> |\n\n## 开放问题  serves: 全文\n\n（说明：Google 的 Open Questions。每个问题给选项、负责人、截止；评审当天没收敛的争议项也记在这里，由决策人在 48 小时内单独裁定。）\n\n| 问题 | 选项 | 负责人 | 截止 |\n|---|---|---|---|\n| <待定问题> | <备选项> | <谁> | <日期 / 已决：结论> |\n\n## 附录  serves: 全文\n\n（说明：原型链接、压测报告、调研原始记录、成本测算、相关 ADR 编号、评审意见与变更历史。评审给出结论后，本文件冻结为**基线**；后续变更出新版本，而不是原地改。）\n\n- **原型与验证材料**：<链接>\n- **相关文档**：<PRD / ADR / 上游设计>\n- **评审记录**：<评审日期、结论、未闭环项>\n- **变更历史**：<何时改了什么、为什么>\n",
    "example": "---\ntitle: 内容格式规则引擎 设计文档\nstatus: approved\nowner: 插件组\nreviewers: 架构组、宿主组、文档组\nprd: examples/file-format-specs/prd/example.md\nserves: FR-1、FR-2、FR-3、FR-4、FR-5、FR-6、NFR-1、NFR-2、NFR-3\ncreated: 2026-10-14\nupdated: 2026-10-15\n---\n\n# 内容格式规则引擎 设计文档  serves: FR-1\n\n## 摘要  serves: 全文\n\n- **问题**：文档结构判据写死在插件代码里，项目想加一条自己的判据就要改代码、重新构建，于是要求都退化成 prompt 里靠模型自觉的一句话。\n- **方案**：把判据从代码搬进项目自己的 `.dsh/file-format-specs/<type>/spec.yaml`——文档解析成事实，规则写成条件树，内置原语与用户脚本都只是引擎里的函数；校验挂在 write/edit 落盘之后的 post-execute 钩子上。\n- **影响面**：新增 `src/content-format/`（匹配、解析、原语、规则引擎、脚本沙箱、反馈渲染）；只读宿主的 `tools/post-execute`，不改宿主、不改工具入参、不回滚已落盘文件。\n\n## 背景与问题  serves: 全文\n\n### 需求来源\n\n| 需求编号 | 原始诉求 | 本设计如何回应 |\n|---|---|---|\n| FR-1 | 「项目想加一条判据，必须改插件发版」 | 规则数据化：类型目录 = 文档类型，`spec.yaml` 声明规则；mtime 签名缓存失效，改文件即生效 |\n| FR-2 | 「只报缺章节，不说为什么、也不给形状」 | 条件树求值（`all/any/not/path/each/count/fn`）保住表达力，违规带 rule id、行号与 message |\n| FR-3 | 「同一条判据要在多处重复计算」 | 前向链 `derive`：派生事实一次算好，后续规则直接引用；后一条可见前一条 |\n| FR-4 | 「每加一条判据就加一段代码」 | 内置原语以 `fn` 形式暴露（`sectionsRequired` / `tableRequired` / `idDetails` / `ids` …），规则只声明参数 |\n| FR-5 | 「有些判据机器判不了，但项目自己判得了」 | `functions` 里写 `expr` / `script` 逃生舱，`node:vm` 白名单上下文 + 1s 超时 |\n| FR-6 | 「被拒之后不知道改成什么样」 | 打回文本附目标模板全文（无模板则按规则反推骨架）+ 填写参考指针 + 剩余次数 |\n| NFR-2 | 「一份 spec 写坏不能拖垮全部校验」 | 单类型加载失败只告警并跳过；脚本抛错只产出一条「函数执行失败」 |\n| NFR-3 | 「用户脚本不能变成任意代码执行」 | `vm` 白名单注入 + 1s 超时；上下文里没有 `require`、`process`、文件系统 |\n\n### 现状与代价\n\n今天加一条判据的路径是：改 `src/` 里的检查函数 → 构建 → 重新安装 bundle → 重启会话。\n代价是三点：接入周期以天计；回归风险高（改的是所有人共用的代码）；判定口径只有一个版本，项目差异只能塞进 prompt。\n\n### 为什么是现在\n\n`tools/post-execute` 钩子已经提供了落盘后的 `after` 全文与 `PostToolDecision`，校验所需的全部输入已经就位；\n而试点项目 3 周内 17 次因结构问题被打回、6 条自定义判据全部搁置——继续把判据留在代码里的成本已经高于把引擎做出来。\n\n## 目标与非目标  serves: 全文\n\n### 目标\n\n- 项目**不改插件代码**即可声明判据：`spec.yaml` 保存后，下一次写文档即按新规则校验；\n- 校验失败给出**可执行的形状**：目标模板 / 骨架 + 违规清单 + 剩余重试次数，目标是一轮改对；\n- 引擎本身可自证：每份示例 spec 的模板都必须通过自己的规则（模板落笔即合规）。\n\n### 非目标\n\n- **不做内容好坏评审**：「这段话写得对不对、清不清楚」机器判不了，硬做会制造误报，交给评审人；\n- **不做跨文档一致性**：本期只看单份文档的形状，不比对两份文档之间的口径（如 PRD 指标名与指标方案是否一一对应）；\n- **不改写文档**：插件只判断与提示，不替 agent 修改正文——写文档的责任留在 agent；\n- **不追溯存量文档**：`diff_mode=delta` 只拦本次新增的违规，旧文件的历史问题不算在本次操作头上。\n\n## 方案总览  serves: FR-2、FR-4\n\n**一句话方案**：把「文档该长什么样」表达成一份 YAML 规则数据，文档解析成事实（标题、表格、正文行、front-matter），规则是事实上的条件树，内置原语与用户脚本都只是引擎里可调用的函数；校验发生在 write/edit 落盘之后，输出 accept / warn / block 三态。\n\n```text\n宿主 write/edit 落盘成功\n  |\n  +-- post-check（tools/post-execute）\n      |\n      +-- match：按文件名 + match_path 选 spec（priority 降序，首个命中）\n      |     |\n      |     +-- 未命中 --> accept（零正文）\n      |\n      +-- validateDocument\n      |     |\n      |     +-- parse：标题 / 表格 / 正文行 / front-matter（跳过代码围栏）\n      |     +-- derive：前向链派生事实（countIds / 用户函数）\n      |     +-- rules：条件树求值 --> 违规列表（聚合，带行号）\n      |     +-- delta：减去 before 已有的违规 key\n      |\n      +-- report：accept | warn+指引 | block+差异清单+目标模板\n```\n\n**关键概念**\n\n- **事实 Facts**：解析结果铺开的一层只读数据（`doc` / `frontmatter` / `headings` / `tables` / `bodyLines` / `text` / `fileName` / `relPath` / `specName`），派生事实也写回这一层。\n- **条件树**：`{ path | each | count | fn | all | any | not }` 的递归结构，叶子产出 `{ ok, failures }`；一个 rule 的 `assert` 就是一棵树。\n- **内置原语**：`PRIMITIVES` 表里的纯函数（`ParsedDoc + 参数 → 失败列表`），只判机器能证伪的结构事实。\n- **delta 归责**：违规的 `key` 是稳定标识；`before` 里已存在的 key 不再计入本次新增违规。\n\n## 架构与依赖  serves: FR-1、FR-2\n\n- **模块划分**\n  - `spec.ts`：类型目录加载（`spec.yaml` + 约定 `template.md` / `example.md`）、`normalizeSpec`、mtime 签名缓存；\n  - `match.ts`：glob 与关键词匹配、priority 排序、首个命中；\n  - `parse.ts`：行扫描解析（标题层级、表格、代码围栏跳过、front-matter）；\n  - `primitives.ts`：内置原语，每条失败带 `key` 与行号；\n  - `rules/`：条件求值（`condition.ts`）、规则引擎（`engine.ts`）、路径解析（`path.ts`）、运算符（`operators.ts`）、函数注册（`builtin.ts`）；\n  - `script.ts`：`node:vm` 沙箱，跑 `expr` 与 `script`；\n  - `report.ts` / `skeleton.ts`：打回文本渲染；无模板时从规则反推骨架；\n  - `post-check.ts`：钩子装配（匹配 → 校验 → 决策），与宿主 `PostToolDecision` 的唯一接触面。\n- **依赖方向**：`post-check → validate → engine → {condition, primitives, script}`，`report` 只读 `validate` 的结果；`spec` 是数据来源，不被反向依赖。**无环**——这是可单测的前提：`validateDocument` 不碰文件系统。\n- **外部依赖**：宿主 `tools/post-execute` 与 `PostToolDecision`（阻塞项）；`js-yaml`（解析 spec）；`node:vm`（脚本沙箱，可选降级为「不支持 script」）。\n- **与既有架构的差异**：校验不再写死在 `src/`，运行时读用户工作区的 YAML——插件行为开始依赖工作区数据，因此缓存失效必须按文件 mtime 而不是进程生命周期。\n\n## 数据模型  serves: FR-1、FR-3\n\n- **实体与字段**\n  - `FormatSpec`：`name` / `ext?` / `priority` / `match[]` / `matchPath[]` / `template?` / `example?` / `mode` / `enforceOn[]` / `diffMode` / `maxAttempts` / `onExhausted` / `rules[]` / `derive[]` / `functions{}`。\n  - `ParsedDoc`：`frontmatter{}` / `headings[]`（`text` / `level` / `line`）/ `tables[]`（`header[]` / `rows[][]` / `line`）/ `bodyLines[]` / `bodyLineNos[]` / `lineCount` / `charCount`。\n  - `Violation`：`checkId` / `type` / `severity` / `key` / `message` / `line?`。\n  - `FormatReport`：`spec` / `violations` / `errors` / `warnings` / `newErrors` / `newWarnings`。\n- **约束与不变量**\n  - `match` 与 `matchPath` 不能同时为空（否则会匹配一切）——加载期拒绝，而不是运行期兜底；\n  - `name` 取自目录名，同一工作区内唯一；`priority` 决定首个命中，同级按名称稳定排序；\n  - delta 的 `key` 必须稳定：`rule.id + '|' + (failure.key ?? rule.key ?? message)`，不得含行号（否则改一行就重新报）；\n  - 派生事实后一条可见前一条，形成前向链；不得回写 `doc`。\n- **迁移与回填**：无需迁移——校验不落盘、不留存；旧文档靠 `diff_mode=delta` 天然不追溯。\n- **生命周期**：spec 按「目录 + 四个文件 mtime」签名缓存，改文件即失效；文档解析结果与违规列表都是单次调用内的临时对象。\n\n## 接口设计  serves: FR-1、FR-6\n\n| 编号 | 接口 | 输入 | 输出 | 失败与错误 | 兼容性 |\n|---|---|---|---|---|---|\n| IF-1 | 宿主钩子 `tools/post-execute` | `exec`（工具名与 arguments）、`result.value.{path,operation,before,after}`、`next()` | `PostToolDecision`：`accept` 或 `block{feedback[]}` | 不抛异常；内部失败一律降级为 `accept`（最多附一条 warning） | 只读 `value`，宿主冻结 `arguments`；宿主新增字段默认忽略 |\n| IF-2 | `validateDocument(spec, after, before, templateText?, options?)` | spec、落盘后全文、落盘前全文或 null、模板正文、`{fileName, relPath, scriptTimeoutMs}` | `FormatReport` | 不抛；脚本抛错或超时变成一条 `severity=error` 的违规 | `FormatReport` 字段只增不改；`options` 全可选；`before=null` 等价 strict |\n| IF-3 | `spec.yaml` 文件契约 | 类型目录下的 YAML：`match` / `match_path` / `rules` / `derive` / `functions` … | 加载后的 `FormatSpec` | YAML 非法 → `logger.warn` + 跳过该类型；`match` 与 `match_path` 同时为空 → 拒绝加载 | 顶层未知键忽略；`rules[].require` 作为 `assert` 的别名保留 |\n| IF-4 | 自定义函数沙箱（`expr` / `script`） | 表达式或脚本文本；上下文白名单 `doc/text/fileName/relPath/specName/api` | 通过（`undefined`/`null`/`true`/空数组）或违规（`string` / `{message,line,key,severity}` / 数组） | 抛错或 1s 超时 → 一条「函数执行失败」，其余规则照跑 | `api` 白名单只增不减；返回值接受三种形态 |\n\n#### IF-1 宿主钩子决策协议\n\n**语义**\n\nwrite/edit 落盘成功、且宿主给出 `after` 全文之后被调用。顺序固定：按 `relPath` + 文件名匹配 spec → 未命中直接 `accept` → 命中则加载模板与 example、调用 `validateDocument` → 按 `mode` 与 delta 结果决定 `accept` / `warn` / `block`。block 只改变工具结果，**不回滚已落盘内容**——这是刻意的：文件已经写对一半，回滚会让 agent 丢失已有进度。\n\n**错误码**\n\n本接口没有异常码，只有三条降级路径，全部落到 `accept`：\n\n- 未命中 spec → 零正文放行（无法可依，不误伤）；\n- spec 非法 → 一条 warning 指向 spec 文件，且**不伪装成文档违规**；\n- 引擎内部异常 → 记一条错误文本，放行。\n\n`block` 的 `feedback[].text` 必须包含：本次新增违规清单（rule id + 行号 + 建议）、历史违规计数、目标模板或骨架、填写参考路径、剩余次数。\n\n**兼容性**\n\n宿主升级时按「缺字段 = 未命中」处理，不做版本嗅探；插件只读 `arguments`，不修改入参；\n`next()` 必须恰好调用一次，避免短路宿主链上的其它钩子。\n\n#### IF-2 validateDocument\n\n**语义**\n\n纯函数校验：解析 → 构建事实 → `derive` 前向链 → 规则求值（priority 降序，`when` 守卫）→ 按 `diffMode` 归责。不触文件系统、不做 IO，因此可用纯文本单测覆盖。\n\n**错误码**\n\n不抛异常。两个特例：\n- 用户函数抛错或超时 → 产出一条 `checkId = <函数名>` 的错误文本「函数执行失败」，继续跑其它规则；\n- 依赖失败事实的规则照常求值（事实缺失即条件不成立），不级联报错。\n\n**兼容性**\n\n`FormatReport` 只增字段，不改语义；`violations` 与 `errors` 的口径区别（全量 vs 仅 error 级）必须保持稳定，因为反馈渲染与统计都依赖它；`scriptTimeoutMs` 可作为测试注入项，默认 1000ms。\n\n#### IF-3 spec.yaml 文件契约\n\n**语义**\n\n一个文档类型一个目录：目录名即 `name`，同目录 `template.md` 与 `example.md` 按约定自动挂上，无需在 YAML 里写。\n`match` 判文件名（无 `*?` 按关键词包含，否则按 glob），`match_path` 判相对路径，两者都写时必须同时满足。\n`rules` 是条件树数组，`derive` 是前向链，`functions` 是用户函数表。\n\n**错误码**\n\n- YAML 语法错误或 `normalizeSpec` 抛错 → `logger.warn('format spec <name>/ 非法——<原因>')` 并跳过该类型，其它类型照常；\n- `match` 与 `match_path` 同时缺失 → 视为配置错误拒绝加载（绝不匹配一切）；\n- `functions` 里声明的函数名与内置函数重名 → 以内置为准并告警。\n\n**兼容性**\n\n顶层未知键忽略（允许项目写注释性字段）；`rules[].require` 保留为 `assert` 别名；\n`mode` / `diff_mode` / `max_attempts` / `on_exhausted` 缺省时按 `block` / `delta` / `3` / `allow` 处理，旧 spec 不需要补齐。\n\n#### IF-4 自定义函数沙箱\n\n**语义**\n\n`functions` 里用 `expr`（按真假判定）或 `script`（返回违规列表）注册；脚本上下文只注入白名单：`doc`、`text`、`fileName`、`relPath`、`specName`、`api`。`api` 提供 `hasSection` / `section` / `collectIds` / `frontmatter` / `violation`。\n返回值协议：`undefined` / `null` / `true` / 空数组 = 通过；string、`{message, line, key, severity}`、或它们的数组 = 违规。\n\n**错误码**\n\n抛错与超时都归为一条「函数执行失败」，`checkId` 为函数名——**绝不拖垮写文件**；`expr` 为假时报 rule 自身的 `message`（而不是函数返回的文本），因为判据属于规则、实现属于函数。\n\n**兼容性**\n\n`api` 白名单只增不减（删一个方法会静默破坏项目已有的 spec）；返回值三种形态必须长期同时接受；\n脚本内不得依赖 `this`、模块系统或任何 IO，白名单之外一律 `undefined`。\n\n**幂等与重试**\n\n函数在同一次校验内可能被多条规则调用，必须是纯函数：只读事实、不写外部状态。\n没有重试语义——超时即失败，不做第二次执行。\n\n## 备选方案  serves: 全文\n\n| 方案 | 一句话说明 | 优点 | 代价 | 为什么未选 |\n|---|---|---|---|---|\n| A（选用） | 规则数据化 + 条件树引擎 + 内置原语 | 项目零代码接入；判据可单测；示例可自证 | 引擎与沙箱要自己写，抽象成本前置 | — |\n| B | 继续用写死的检查函数，只把阈值参数化 | 实现最省，无新概念 | 判据表达力仍受代码限制；新判据仍要发版 | 正是本期要消掉的那笔成本 |\n| C | 把文档规范写进 prompt 让模型自觉遵守 | 零实现 | 不可机械验证、不可回归、无法定位误报 | 试点已证伪：结构问题仍占到 17 次打回 |\n| D：什么都不做 | 维持现状，靠评审人挑 | 无成本 | 评审时间被结构问题吃掉，判据继续搁置 | 打回率与搁置数都在上升 |\n\n## 四风险与证据  serves: 全文\n\n| 风险类型 | 判断问题 | 现有证据 | 结论 |\n|---|---|---|---|\n| 价值 | 项目方真的愿意维护 spec.yaml 吗 | 本仓库自用三份 spec（prd / metrics / design）驱动同一个引擎，且示例模板受守护测试约束；试点 6 条搁置判据待 2 周内迁入 | 部分 |\n| 可用性 | 被打回的 agent 能照着指引改对吗 | PRD 示例里内联了打回文本原型（含新增/历史分离、目标结构、剩余次数）；`test/format.test.ts` 的 post-execute 集成用例覆盖 accept / block / 放行三态 | 部分 |\n| 可行性 | 规则引擎与沙箱建得出来吗 | 引擎已落地：条件树、量词、`fn`、`derive`、`when` 守卫、四类内置原语均有单测；死循环脚本被 1s 超时截断有专测 | 已验证 |\n| 商业可行性 | 成本与合规能接受吗 | 纯本地执行、零网络、零外部服务；不落盘不采集，无 PII 流入 | 已验证 |\n\n**未验证项的补课计划**\n\n- 价值风险：2 周内在试点项目落地首批 spec，统计「自建 spec 的项目数 ≥ 2」；不达标先发布内置默认规范，把自定义能力后置；\n- 可用性风险：用 6 份真实被打回文档做 agent 修复演练，记录「下一次 write 即零 error」的比例（目标 ≥ 80%）。\n\n## 失败模式与回滚  serves: NFR-2、NFR-6\n\n| 失败场景 | 触发条件 | 用户可见影响 | 检测手段 | 回滚动作 | 决策人 |\n|---|---|---|---|---|---|\n| 规则写错导致误拦 | spec 的判据过严或写法有误 | agent 反复被同一条规则打回 | 结构化日志里的 block 率与同一 checkId 重复率 | 把该 spec 的 `mode` 改为 `warn` 或 `off` | 项目维护者 |\n| 模板与规则漂移 | 模板 H2 与 `sectionsRequired` 不一致 | 照着模板写仍被打回 | 守护测试「每份示例模板都通过它自己的 spec」 | 修模板或修规则，二者必须一致 | 插件组 |\n| 脚本死循环 | `script` 里出现无出口循环 | 该校验耗时被截断，产出一条失败 | 单测覆盖超时路径；日志里出现「函数执行失败」 | 修脚本；必要时删除该函数改用内置原语 | 规则作者 |\n| 脚本抛错 | 引用未定义变量、越权访问 | 一条函数失败，其余规则照跑 | 同上 | 同上 | 规则作者 |\n| 打回文本过长 | 模板很大且违规很多 | block 反馈吃掉上下文预算 | 反馈字数与模板行数 | 超阈值改为「指针 + 节清单」 | 插件组 |\n| 匹配到错误 spec | 文件名关键词过宽（如裸 `design`） | 文档被无关规则校验 | 误报率与 spec 命中日志 | 收紧 `match`，改用 `match_path` | 项目维护者 |\n\n- **开关**：`mode: block | warn | off`，粒度是单个文档类型（一个 spec 目录）；`diff_mode` 决定是否追溯存量。\n- **回滚演练**：在试点项目把 design spec 切回 `warn` 跑一轮，确认不阻断写入且能正常提示；预期 1 分钟内生效（mtime 缓存失效，无需重启）。\n- **不可逆动作**：**无**。校验不回滚、不改写正文；唯一的写操作是插件自身 bundle 安装，与本引擎无关。\n\n## 跨关注点  serves: NFR-1、NFR-3、NFR-4、NFR-5\n\n| 关注点 | 结论 | 依据与措施 |\n|---|---|---|\n| 安全 | 用户脚本不得成为任意代码执行入口 | `node:vm` 白名单上下文，无 `require` / `process` / IO；默认 1s 超时截断 |\n| 隐私与合规 | 不采集、不落盘、不外发 | 只读 `after` 全文并内存校验；无网络调用；日志只记 spec 名、规则 id、违规数与耗时 |\n| 成本 | 近似为零 | 无外部服务、无模型调用；按 mtime 签名缓存 spec，单次校验只解析一次文档 |\n| 可观测性 | 误报与放行可统计 | 每次 block 记结构化日志；`on_exhausted=allow` 的放行单独计数（区别于真正通过） |\n| 性能与容量 | 单次校验 P95 ≤ 50ms（1000 行文档） | 单遍行扫描解析；跳过代码围栏；违规全量聚合但一次渲染，不做 N 次遍历 |\n| 文档与支持 | 项目方能自助排错 | `docs/template-authoring.md` 定义模板契约；示例 spec 即活文档；spec 非法时告警直接指向文件 |\n\n## 交付拆分与里程碑  serves: 全文\n\n| 里程碑 | 内容 | 出口判据 | 负责人 | 目标日期 |\n|---|---|---|---|---|\n| M1 | 匹配 + 解析 + 内置原语 + 规则引擎 | 原语单测通过；`matchSpec` 首个命中与 priority 用例通过 | 插件组 | 2026-10-20 |\n| M2 | 动态函数沙箱 + `derive` + 反馈渲染与骨架 | 死循环被超时截断；无模板时能生成骨架 | 插件组 | 2026-10-24 |\n| M3 | 三份示例 spec + 模板 + 守护测试 | 模板零 error、示例零 error、负例探针逐条会拦人 | 插件组 + 文档组 | 2026-10-28 |\n| M4 | 试点 warn → block | warn 期误报率 < 5%，随后切 block | 插件组 | 2026-11-10 |\n| M5 | 全量 | 试点复盘通过；agent 一次修复率 ≥ 80% | 插件组 | 2026-11-24 |\n\n## 需求追溯  serves: 全文\n\n| 需求编号 | 设计节 | 测试用例 | 指标 |\n|---|---|---|---|\n| FR-1 | 数据模型 / 接口设计（IF-3） | test/format.test.ts「匹配：优先级与首个命中」；「示例规范守护」 | 自定义判据接入成本 |\n| FR-2 | 方案总览 / 架构与依赖 | test/rules.test.ts「each + where：每个 H2 必须 serves」；「count 量词」；「not / any 组合」 | agent 一次修复率 |\n| FR-3 | 数据模型（前向链不变量） | test/rules.test.ts「derive + 用户 expr 函数」 | agent 一次修复率 |\n| FR-4 | 架构与依赖（primitives） | test/rules.test.ts「fn 调内置函数 hasSection」；test/format.test.ts「内置原语」 | agent 一次修复率 |\n| FR-5 | 接口设计（IF-4） | test/format.test.ts「动态代码：expr / script」；「脚本抛错 → 一条错误，不崩」；「死循环被超时截断」 | agent 一次修复率 |\n| FR-6 | 接口设计（IF-1 反馈字段） | test/format.test.ts「打回指引：目标模板与骨架」；「post-execute 集成」 | agent 一次修复率 |\n| NFR-1 | 跨关注点（性能与容量） | 待补基准用例：1000 行文档单次校验耗时 | 单次校验耗时 P95 |\n| NFR-2 | 失败模式与回滚（spec 非法） | test/format.test.ts「示例规范守护」；加载非法 spec 的跳过行为 | 自定义判据接入成本 |\n| NFR-3 | 接口设计（IF-4 超时） | test/format.test.ts「死循环被超时截断」 | 不适用（合规约束，非业务指标） |\n| NFR-6 | 方案总览（delta 归责） | test/format.test.ts「delta：只拦新增违规」；「新建（before=null）等价 strict」 | 单份需求结构化返工次数 |\n\n## 常见问题  serves: 全文\n\n| 问题 | 回答 |\n|---|---|\n| 项目方最可能抱怨什么？ | 「我又多了一份要维护的 YAML」。对策是把 spec 控制在声明式规则内，并且用示例件（`example.md`）当活文档；真不愿维护的项目继续走内置默认规范。 |\n| 六个月后这套东西会变成什么负担？ | 最可能的负担是 spec 与模板漂移、以及原语语义被误用。防法是守护测试：模板必须通过自己的 spec，每份示例必须零 error，改语义就会有测试红。 |\n| 文档量涨 10 倍先坏在哪里？ | 先坏在解析与表格扫描是整篇遍历（每份文档 O(行数)），以及 block 反馈过长。前者靠 P95 基准用例暴露，后者靠「超阈值转指针」。 |\n| 谁会在半夜被叫起来？他手上有什么？ | 不会有人被叫起来——插件在本地、无服务端。最坏情况是 agent 被持续误拦，此时维护者手上有：结构化日志（spec 名 / 规则 id / 违规数）、spec 文件本身、以及把 `mode` 改成 `warn` 这个开关。 |\n| 数据错了怎么修？修得回来吗？ | 校验不落盘、不留存，所以没有「错数据」要修；误判只影响当次反馈，改 spec 后下一次写入即修正，无需回填。 |\n| 这个决定错了多久能发现？ | 价值假设（项目方愿维护 YAML）在 2 周试点内见分晓——判据是「自建 spec 的项目数 ≥ 2」；可用性假设用 6 份真实打回文档的修复演练，一轮即知。 |\n| 为什么不直接用 JSON Schema 校验文档结构？ | 我们的判据不是纯 schema：需要「每个 H2 带 serves」「清单编号必须在明细里出现」这类跨行、跨节约束，还要允许项目写脚本。JSON Schema 表达不了，且它没有 delta 归责与反馈渲染。 |\n\n## 开放问题  serves: 全文\n\n| 问题 | 选项 | 负责人 | 截止 |\n|---|---|---|---|\n| 大模板在 block 文本里是否改为「指针 + 节清单」 | 全文内联 / 超阈值（60 行）转指针 | 插件组 | 2026-10-30 |\n| `file_check` 是否做全仓巡检（而非只在 write/edit 时校验） | 做 / 不做 | 插件组 | 2026-11-15 |\n| 内置默认规范是否随包发行 | 随包 / 项目自建 | 架构组 | 2026-11-20 |\n\n## 附录  serves: 全文\n\n- **原型与验证材料**：打回文本原型见 PRD 示例的「文本交互原型」；无模板时的骨架输出由 `skeleton.ts` 生成，测试覆盖于「打回指引：目标模板与骨架」。\n- **相关文档**：`examples/file-format-specs/prd/example.md`（需求来源）、`docs/content-validation-design.md`（三环节全景）、`docs/template-authoring.md`（模板契约）。\n- **评审记录**：2026-10-14 设计评审通过（架构组 + 宿主组 + 文档组）；未闭环项 = 开放问题前两条，各有负责人与截止。\n- **变更历史**：2026-10-14 初稿（含接口 IF-1～IF-4 与四风险证据）；2026-10-15 按评审意见补「失败模式与回滚」的不可逆动作结论、把性能口径从「未测」改为 P95 ≤ 50ms。\n"
  },
  "metrics": {
    "spec": "# .dsh/file-format-specs/metrics/spec.yaml —— 埋点与指标方案格式规范\n# 结构取自四条主线的交集：\n#   Google   ：Goals → Signals → Metrics（HEART）+ OEC / 实验设计 + 上线前可观测性\n#   Amazon   ：输入指标 vs 输出指标 + WBR 节奏 + PR-FAQ 的「怎么衡量成功」\n#   Cagan    ：价值 / 可用性 / 可行性 / 商业可行性 四风险的可证伪假设\n#   Wiegers  ：指标也是需求——可量化、可验证、可追溯（指标 ↔ 埋点双向追溯）\next: md\npriority: 85\n# 关键词包含匹配：metrics 能命中 metrics.md / 埋点-xxx.md / 指标方案.md\nmatch:\n  - \"metrics\"\n  - \"埋点\"\n  - \"指标方案\"\n  - \"instrumentation\"\nmode: block\ndiff_mode: delta\nmax_attempts: 3\non_exhausted: allow\n\n# —— 规则引擎 ——\nderive:\n  - fact: metricIdCount          # 全文数 M-1 这类编号（含表格单元格）\n    fn: countIds\n    args: [[\"M\"]]\n\nfunctions:\n  hasOwner:\n    expr: \"!!(frontmatter.owner || frontmatter.owner_team)\"\n\n  noPlaceholder:\n    expr: \"!/TODO|TBD|待补充/.test(text)\"\n\n  # 指标 ↔ 埋点双向追溯（Wiegers）：每个指标明细必须引用至少一个埋点编号；\n  # 每个埋点编号必须至少被一个指标引用。返回违规列表。\n  metricEventTrace:\n    script: |\n      const idxOf = new Map()\n      doc.bodyLineNos.forEach((n, i) => idxOf.set(n, i))\n      const blockOf = (id) => {\n        const h = doc.headings.find((x) => new RegExp('^' + id + '\\\\b').test(x.text.trim()))\n        if (!h) return ''\n        const start = idxOf.get(h.line)\n        if (start === undefined) return ''\n        let end = doc.bodyLines.length\n        for (const o of doc.headings) {\n          if (o.line <= h.line || o.level > h.level) continue\n          const j = idxOf.get(o.line)\n          if (j !== undefined && j < end) end = j\n        }\n        return doc.bodyLines.slice(start, end).join('\\n')\n      }\n      const metricIds = []\n      const eventIds = []\n      for (const t of doc.tables) {\n        const head = t.header.join('|')\n        if (head.indexOf('编号') >= 0 && head.indexOf('指标') >= 0) {\n          for (const r of t.rows) { const v = String(r[0] || '').trim(); if (/^M-\\d+$/.test(v)) metricIds.push(v) }\n        }\n        if (head.indexOf('事件名') >= 0) {\n          for (const r of t.rows) { const v = String(r[0] || '').trim(); if (/^EV-\\d+$/.test(v)) eventIds.push(v) }\n        }\n      }\n      const refsOf = new Map()\n      const out = []\n      for (const m of metricIds) {\n        const refs = api.collectIds(blockOf(m), ['EV'])\n        refsOf.set(m, refs)\n        if (refs.length === 0) out.push(api.violation(m + ' 的明细没有引用任何埋点编号（EV-x）：指标必须能追到埋点'))\n      }\n      for (const e of eventIds) {\n        const used = metricIds.some((m) => (refsOf.get(m) || []).indexOf(e) >= 0)\n        if (!used) out.push(api.violation(e + ' 没有被任何指标引用：埋点要么删掉，要么补上它服务的指标'))\n      }\n      return out\n\nrules:\n  - id: fm\n    assert:\n      fn: frontmatterRequired\n      args:\n        - keys: [title, status]\n  - id: status-enum\n    assert: { fn: frontmatterEnum, args: [{ key: status, values: [draft, review, approved, superseded] }] }\n\n  # 必备章节，按发布顺序（结构节只认 H2）\n  - id: sections\n    assert:\n      fn: sectionsRequired\n      args:\n        - order: true\n          headings:\n            - 摘要\n            - 目标与决策用途\n            - 假设与风险验证\n            - 指标框架\n            - 指标体系\n            - 指标定义\n            - 反指标与护栏\n            - 埋点清单\n            - 实验与灰度设计\n            - 数据链路与质量\n            - 看板与复盘节奏\n            - 上线验收与签署\n            - 开放问题\n            - 附录\n\n  # 关键表格：缺表 / 缺列都会被打回\n  # 决策表：Google 的 Goals——不能改变决策的指标不写\n  - id: decision-table\n    assert: { fn: tableRequired, args: [{ under: 目标与决策用途, header: [决策, 依据指标, 达标时怎么做, 不达标时怎么做] }] }\n  # 四风险表：Cagan 价值 / 可用性 / 可行性 / 商业可行性\n  - id: risk-table\n    assert: { fn: tableRequired, args: [{ under: 假设与风险验证, header: [风险类型, 假设, 验证方式, 判定标准], min_rows: 4 }] }\n  # Goals → Signals → Metrics（HEART）\n  - id: heart-table\n    assert: { fn: tableRequired, args: [{ under: 指标框架, header: [HEART 维度, 目标, 信号, 指标, 服务风险] }] }\n  # Amazon 输入 / 输出 / 诊断分层\n  - id: hierarchy-table\n    assert: { fn: tableRequired, args: [{ under: 指标体系, header: [层级, 指标, 作用, 是否可干预] }] }\n  - id: metric-table\n    assert: { fn: tableRequired, args: [{ under: 指标定义, header: [编号, 指标, 层级, 方向, 基线, 目标, 时间窗, 阈值] }] }\n  # 每个 M-x 都要有明细：定义 / 计算口径 / 数据来源 / 验证方式 必填\n  - id: metric-details\n    assert: { fn: idDetails, args: [{ under: 指标定义, fields: [定义, 计算口径, 数据来源, 验证方式], optional: [分段, 已知偏差] }] }\n  - id: guardrail-table\n    assert: { fn: tableRequired, args: [{ under: 反指标与护栏, header: [主指标, 护栏指标, 阈值, 触发动作] }] }\n  - id: event-table\n    assert: { fn: tableRequired, args: [{ under: 埋点清单, header: [编号, 事件名, 触发时机, 关键属性, 上报方式, 隐私等级, 负责人] }] }\n  # 实验 / 灰度：每个设定都要给理由，OEC 与停止规则不许省\n  - id: experiment-table\n    assert: { fn: tableRequired, args: [{ under: 实验与灰度设计, header: [变量, 设定, 理由], min_rows: 6 }] }\n  - id: pipeline-table\n    assert: { fn: tableRequired, args: [{ under: 数据链路与质量, header: [环节, 数据源, 延迟, 校验规则, 断流告警] }] }\n  - id: cadence-table\n    assert: { fn: tableRequired, args: [{ under: 看板与复盘节奏, header: [节奏, 看什么, 谁看, 触发动作] }] }\n  # 埋点是发布的一部分：验收项 + 验证方式 + 负责人\n  - id: acceptance-table\n    assert: { fn: tableRequired, args: [{ under: 上线验收与签署, header: [验收项, 合格标准, 验证方式, 负责人], min_rows: 4 }] }\n  - id: open-questions\n    assert: { fn: tableRequired, args: [{ under: 开放问题, header: [问题, 选项, 负责人, 截止] }] }\n\n  - id: has-owner\n    when: { path: \"frontmatter.status\", op: \"notEmpty\" }   # 守卫：只对有 status 的文档生效\n    assert: { fn: \"hasOwner\", message: \"埋点与指标方案必须有 owner 或 owner_team\" }\n    priority: 10\n\n  - id: at-least-one-metric\n    assert: { path: \"metricIdCount\", op: \"gte\", value: 1, message: \"至少一条指标编号（M-1…）\" }\n\n  # 指标 ↔ 埋点双向追溯（script 自定义函数）\n  - id: metric-event-trace\n    assert: { fn: metricEventTrace }\n\n  - id: no-placeholder\n    severity: warning\n    assert: { fn: noPlaceholder, message: \"文档里不能留 TODO / TBD / 待补充\" }\n",
    "template": "---\ntitle: <产品 / 功能名> 埋点与指标方案\nstatus: draft\nowner: <负责人>\nprd: <关联 PRD 路径>\ncreated: <YYYY-MM-DD>\nupdated: <YYYY-MM-DD>\n---\n\n# <产品 / 功能名> 埋点与指标方案\n\n## 摘要\n\n（说明：3 行以内回答三问——服务哪个决策 / 覆盖哪次发布 / 谁按什么节奏看它。指标方案不是数据字典，只写\"会被用来做决定\"的那部分。）\n\n- **服务决策**：<要用数据回答的那个问题>\n- **覆盖范围**：<版本 / 功能 / 实验编号>\n- **读者与节奏**：<谁看、多久看一次>\n\n## 目标与决策用途\n\n（说明：Google 要求先写 Goals——不能改变任何决策的指标不要写进本文。逐行写清\"看到什么数就做什么决定\"，达标与不达标都要有动作。）\n\n| 决策 | 依据指标 | 达标时怎么做 | 不达标时怎么做 |\n|---|---|---|---|\n| <要决定的事> | <M-x> | <继续放量 / 全量> | <回滚 / 改方案> |\n\n## 假设与风险验证\n\n（说明：Cagan 的四项风险——价值 / 可用性 / 可行性 / 商业可行性。每项给一个可证伪的假设（如果…那么…因为…）和判定标准；只写\"我们会持续观察\"等于没写。）\n\n| 风险类型 | 假设 | 验证方式 | 判定标准 |\n|---|---|---|---|\n| 价值 | <如果做 X，那么指标 Y 会变化，因为 Z> | <实验 / 灰度 / 访谈 / 埋点> | <达到什么数算成立> |\n| 可用性 | <如果这样交互，那么完成率会提升，因为…> | <可用性测试 / 任务成功率> | <达到什么数算成立> |\n| 可行性 | <如果按此方案实现，那么性能与成本可控，因为…> | <压测 / 成本核算> | <P95 与单次成本上限> |\n| 商业可行性 | <如果定价与成本如此，那么单位经济成立，因为…> | <毛利测算 / 付费意愿> | <毛利或回收期下限> |\n\n## 指标框架\n\n（说明：Google 的 Goals → Signals → Metrics（HEART）——先写目标，再写能观察到的信号，最后才落到能算出来的指标；反过来做就是拍脑袋选指标。）\n\n| HEART 维度 | 目标 | 信号 | 指标 | 服务风险 |\n|---|---|---|---|---|\n| <Engagement> | <要达到什么> | <用户会表现出什么> | <M-x> | <价值> |\n\n## 指标体系\n\n（说明：Amazon 的输入与输出之分——北极星是输出指标，只看结果；输入指标必须可控且领先，用来推动；诊断指标负责解释波动。输出指标不可干预，别拿它当行动目标。）\n\n| 层级 | 指标 | 作用 | 是否可干预 |\n|---|---|---|---|\n| 北极星（输出） | <M-x> | <判定成败> | 否 |\n| 输入 | <M-x> | <推动哪个前置量> | 是 |\n| 诊断 | <M-x> | <解释波动 / 定位环节> | 是 |\n\n## 指标定义\n\n（说明：每个指标一行总览 + 一段明细。定义要精确到\"两个人按同一口径能算出同一个数\"（Wiegers 的可验证性）；\"验证方式\"指怎么证明这个数本身是对的，不是怎么用这个数。总览表的编号 = 明细小节的编号。）\n\n| 编号 | 指标 | 层级 | 方向 | 基线 | 目标 | 时间窗 | 阈值 |\n|---|---|---|---|---|---|---|---|\n| M-1 | <指标名> | 北极星 | 越大越好 | <当前值 / N/A> | <目标值> | <上线后 N 天> | <越过该值就动手> |\n| M-2 | <护栏指标名> | 护栏 | 越小越好 | <当前值> | <不高于目标值> | <上线后 N 天> | <越过该值即触发动作> |\n\n#### M-1 <指标名>\n\n**定义**\n\n<一句话说清它是什么，并给出计算式，例如\"完成数 / 尝试数\"。>\n\n**计算口径**\n\n<分子、分母、去重维度、时间归属与时区、排除条件（内部流量 / 测试账号 / 机器人）。>\n\n**数据来源**\n\nEV-1（<事件名>）；<库表 / 看板名>。指标必须引用至少一个埋点编号。\n\n**验证方式**\n\n<怎么证明这个数是对的：A/A 试验、与旧报表对账、埋点回放、抽样人工核对；对不上时以哪边为准。>\n\n**分段**（需要按维度拆开看时才写；不需要就删掉这块）\n\n- <按版本 / 平台 / 用户类型 / 入口拆>\n\n**已知偏差**（有已知盲区时才写；不需要就删掉这块）\n\n- <哪类用户或场景统计不到，会影响什么判断>\n\n#### M-2 <护栏指标名>\n\n**定义**\n\n<一句话 + 计算式；护栏指标是\"不能变坏\"的那一个（延迟、失败率、投诉、成本）。>\n\n**计算口径**\n\n<分子、分母、去重维度、时间归属与时区、排除条件。>\n\n**数据来源**\n\nEV-2（<事件名>）；<库表 / 看板名>。\n\n**验证方式**\n\n<与主指标同源的校验方式，或一条独立的对账来源。>\n\n**分段**（需要时才写；不需要就删掉这块）\n\n- <按维度拆>\n\n**已知偏差**（有已知盲区时才写；不需要就删掉这块）\n\n- <盲区与影响>\n\n## 反指标与护栏\n\n（说明：每个主指标至少配一个反指标——只盯一个数，它一定会以你没在看的方式变坏。阈值写\"触发动作\"的那个数，不写\"关注\"。）\n\n| 主指标 | 护栏指标 | 阈值 | 触发动作 |\n|---|---|---|---|\n| <M-x> | <M-x> | <越过该值即触发> | <暂停放量 / 回滚 / 排查> |\n\n## 埋点清单\n\n（说明：缺一个事件，上面的指标就少一个数。事件名与属性名要稳定、可长期沿用，改名等于断数。）\n\n| 编号 | 事件名 | 触发时机 | 关键属性 | 上报方式 | 隐私等级 | 负责人 |\n|---|---|---|---|---|---|---|\n| EV-1 | <对象_动作> | <用户或系统做了什么> | <属性名 / 类型 / 必填 / 枚举> | <客户端 / 服务端 / 批量> | <无 / 含 PII（脱敏方式）> | <谁> |\n| EV-2 | <对象_动作> | <失败 / 异常路径什么时候上报> | <错误码 / 耗时 / 重试次数> | <服务端> | <无> | <谁> |\n\n**命名与属性规范**\n\n- 事件名：<小写下划线，动词在后，例如 file_create>\n- 属性名：<小写下划线；布尔加 is_ 前缀；时间统一 UTC 毫秒>\n- 幂等与去重：<同一动作重复上报按哪个键去重>\n- 上报失败：<重试与补报策略；丢了怎么发现>\n\n## 实验与灰度设计\n\n（说明：只灰度不实验也要写清这几项，否则结论不可信。OEC 是 Google 实验里\"最终用来判定\"的那一个指标；判定规则要在看数之前写下来。）\n\n| 变量 | 设定 | 理由 |\n|---|---|---|\n| 实验单元 | <用户 / 会话 / 工作区> | <为什么按它随机> |\n| 分流与放量 | <1% → 10% → 100%> | <每档看什么数再放> |\n| 样本量与 MDE | <每组样本量 / 最小可检测效应> | <凭什么算出来的> |\n| 最短时长 | <N 天 / 至少 N 个完整周期> | <避开周期性与新奇效应> |\n| OEC | <M-x> | <为什么由它做最终判定> |\n| 停止规则 | <提前停止 / 无效判定 / 分流比例检查> | <谁在什么条件下可以喊停> |\n\n## 数据链路与质量\n\n（说明：从上报到看板每一跳都要能查；校验规则与断流告警是必填——没有告警，数据断了没人知道。）\n\n| 环节 | 数据源 | 延迟 | 校验规则 | 断流告警 |\n|---|---|---|---|---|\n| <上报 → 采集 → 入仓 → 看板> | <表 / 服务> | <分钟 / 小时> | <量级 / 非空 / 对账> | <谁、多久没数据就告警> |\n\n## 看板与复盘节奏\n\n（说明：Amazon 的 WBR 思路——固定节奏、固定看趋势、每个异常必须给出归因与行动项；否则看板会退化成没人看的仪表盘。）\n\n| 节奏 | 看什么 | 谁看 | 触发动作 |\n|---|---|---|---|\n| 每日 | <护栏指标与断流> | <值班> | <超阈值即处理> |\n| 每周 | <主指标与护栏的趋势> | <团队> | <异常归因 + 行动项> |\n| 上线后 N 天 | <全体指标对照目标> | <评审人> | <继续 / 加码 / 回滚> |\n\n## 上线验收与签署\n\n（说明：埋点是发布的一部分，不是发布后补的。下表任一项不合格就不许上线；签署人具体到人。）\n\n| 验收项 | 合格标准 | 验证方式 | 负责人 |\n|---|---|---|---|\n| 埋点齐全 | <清单内所有事件均已上报> | <测试环境回放 / 抓包> | <谁> |\n| 口径正确 | <与指标定义一致，抽样可复现> | <人工比对 / 对账> | <谁> |\n| 看板与告警可用 | <关键指标与告警已就位> | <打开看板与告警确认> | <谁> |\n| 隐私合规 | <无未脱敏个人信息> | <评审记录> | <谁> |\n\n**签署**：<指标负责人 / 技术负责人 / 数据负责人 / 隐私合规，各自确认的日期>\n\n## 开放问题\n\n（说明：每个问题给选项、负责人和截止——Google 的 Open Questions 要求；截止到了没有结论，就写\"已决 + 结论\"。）\n\n| 问题 | 选项 | 负责人 | 截止 |\n|---|---|---|---|\n| <待定问题> | <备选项> | <谁> | <日期 / 已决> |\n\n## 附录\n\n（说明：PRD 与设计文档链接、指标计算脚本、看板地址、变更历史。改口径必须在这里留痕。）\n\n- 相关文档：<PRD / 设计文档链接>\n- 看板与告警：<链接>\n- 变更历史：<何时改了什么；口径变更要写清影响哪些历史结论>\n"
  },
  "prd": {
    "spec": "# .dsh/file-format-specs/prd/spec.yaml —— PRD 文档格式规范\n# 结构参照业界实践：Cagan / Wiegers 的经典 PRD + Google 设计文档的\n# Goals/Non-Goals · Alternatives · Cross-Cutting + Amazon PR-FAQ 的「从客户倒推」。\next: md\npriority: 90\n# 关键词包含匹配：prd 能命中 prd.md / prd-需求.md / 需求-prd.md / PRD.md\nmatch:\n  - \"prd\"\n  - \"产品需求\"\nmode: block\ndiff_mode: delta\nmax_attempts: 3\non_exhausted: allow\n\n# —— 规则引擎 ——\nderive:\n  - fact: requirementCount        # 全文数 FR-1 这类编号（含表格单元格）\n    fn: countIds\n    args: [[\"FR\"]]\n\nfunctions:\n  hasOwner:\n    expr: \"!!(frontmatter.owner || frontmatter.owner_team)\"\n\nrules:\n  - id: fm\n    assert:\n      fn: frontmatterRequired\n      args:\n        - keys: [title, status]\n  - id: status-enum\n    assert: { fn: frontmatterEnum, args: [{ key: status, values: [draft, review, approved, superseded] }] }\n\n  # 必备章节，按发布顺序（结构节只认 H2）\n  - id: sections\n    assert:\n      fn: sectionsRequired\n      args:\n        - order: true\n          headings:\n            - 摘要\n            - 发布公告\n            - 背景与问题\n            - 目标与非目标\n            - 成功指标\n            - 目标用户与场景\n            - 用户旅程与流程设计\n            - 原型与交互说明\n            - 功能需求\n            - 非功能需求\n            - 边界与异常路径\n            - 约束与依赖\n            - 风险与缓解\n            - 常见问题\n            - 备选方案\n            - 发布与回滚\n            - 时间线\n            - 开放问题\n            - 附录\n\n  # 关键表格：缺表 / 缺列都会被打回\n  - id: metrics-table\n    assert: { fn: tableRequired, args: [{ under: 成功指标, header: [指标, 基线, 目标, 时间窗, 衡量方式] }] }\n  - id: fr-table\n    assert: { fn: tableRequired, args: [{ under: 功能需求, header: [编号, 需求, 优先级, 验收判据] }] }\n  - id: fr-details\n    assert: { fn: idDetails, args: [{ under: 功能需求, fields: [描述, 验收标准], optional: [业务规则, 异常与边界, 不在本期范围] }] }\n  - id: nfr-table\n    assert: { fn: tableRequired, args: [{ under: 非功能需求, header: [编号, 类别, 要求, 优先级] }] }\n  - id: risk-table\n    assert: { fn: tableRequired, args: [{ under: 风险与缓解, header: [风险, 概率, 影响, 缓解方案] }] }\n  - id: timeline-table\n    assert: { fn: tableRequired, args: [{ under: 时间线, header: [里程碑, 时间, 依赖] }] }\n  - id: open-questions\n    assert: { fn: tableRequired, args: [{ under: 开放问题, header: [问题, 选项, 负责人, 截止] }] }\n\n  - id: has-owner\n    when: { path: \"frontmatter.status\", op: \"notEmpty\" }   # 守卫：只对有 status 的文档生效\n    assert: { fn: \"hasOwner\", message: \"PRD 必须有 owner 或 owner_team\" }\n    priority: 10\n\n  - id: at-least-one-requirement\n    assert: { path: \"requirementCount\", op: \"gte\", value: 1, message: \"功能需求至少一条编号（FR-1…）\" }\n",
    "template": "---\ntitle: <产品 / 功能名> PRD\nstatus: draft\nowner: <负责人>\nreviewers: <评审人>\ncreated: <YYYY-MM-DD>\nupdated: <YYYY-MM-DD>\n---\n\n# <产品 / 功能名> PRD\n\n## 摘要\n\n（说明：3 行以内回答三问——这是什么 / 为什么现在做 / 做完用户得到什么。把价值压进一句话。）\n\n## 发布公告\n\n（说明：Amazon PR-FAQ 的第一步——假设今天就上线，写一段能直接发出去的公告。用客户看得懂的话，不写内部术语。）\n\n**标题**：<一句话说清这是什么>\n**副标题**：<谁受益 + 得到什么>\n**客户问题**：<今天他们卡在哪，用他们的口径>\n**如释重负的一句话**：<一位目标用户会怎么说>\n\n## 背景与问题\n\n（说明：先讲问题，不要先讲方案。用数据、访谈或工单说话，别写\"用户很痛苦\"。）\n\n### 现状\n\n（说明：今天用户是怎么做的？具体到步骤和耗时。）\n\n### 问题\n\n（说明：卡在哪一步、谁受影响、多频繁。）\n\n### 影响与证据\n\n（说明：不做的代价是什么？给出处：访谈几条、工单多少、耗时多久。）\n\n## 目标与非目标\n\n（说明：目标写结果不写功能；非目标写\"看起来也想要、这次明确不做\"的事，各给一句理由。）\n\n### 目标\n\n- <目标（可衡量）>\n\n### 非目标\n\n- <非目标（为什么不做）>\n\n## 成功指标\n\n（说明：上线后怎么判断成了。每个指标都要能读到一个数：基线、目标值、时间窗、衡量方式。）\n\n| 指标 | 基线 | 目标 | 时间窗 | 衡量方式 |\n|---|---|---|---|---|\n| <指标名> | <当前值 / N/A> | <目标值> | <上线后 N 天> | <埋点 / 报表 / 命令> |\n\n## 目标用户与场景\n\n（说明：写清\"谁、在什么场景、今天怎么做、希望变成怎样\"，不要写\"用户\"这种空话。）\n\n| 角色 | 场景 | 痛点 | 现状行为 | 期望行为 |\n|---|---|---|---|---|\n| <角色> | <什么时候用> | <卡在哪> | <现在怎么做> | <希望怎样> |\n\n## 用户旅程与流程设计\n\n（说明：用参与者、编号步骤、ASCII 图和状态表讲清主流程、异常与恢复。不要把 Mermaid / SVG 等渲染图作为唯一事实源；没有多步流程时写「不适用：<理由>」。）\n\n### 参与者与触发条件\n\n- **参与者**：<用户 / agent / 外部系统>\n- **触发条件**：<什么事件启动流程>\n- **前置状态**：<开始前必须成立什么>\n- **结束状态**：<结束后用户与系统分别处于什么状态>\n\n### 主流程（ASCII 图）\n\n（说明：ASCII 图只表达分支和顺序；横向过宽时改用编号步骤。每条主路径都要能追踪到 FR。）\n\n```text\n<触发>\n|\n+-- <分支 A> --> <结果>\n|\n+-- <分支 B>\n    |\n    +-- <条件 1> --> <结果>\n    +-- <条件 2> --> <结果>\n```\n\n### 状态与结果对照表\n\n| 场景 | 触发 / 操作 | 系统结果 | 用户反馈 | 下一步 |\n|---|---|---|---|---|\n| <主场景 / 异常场景> | <输入或事件> | <状态、副作用、数据变化> | <用户看到什么> | <后续动作> |\n\n### 异常与恢复路径\n\n- <失败 / 空态 / 超限 / 并发 / 重试> → <如何提示、如何恢复、是否能退出>\n\n### 流程与需求追踪\n\n| 流程节点 | 对应需求 | 验收判据 |\n|---|---|---|\n| <节点名> | <FR-x / NFR-x> | <AC-x.y / 衡量方式> |\n\n## 原型与交互说明\n\n（说明：涉及新增或修改页面、对话框、路由、关键交互时，原型链接为 Must；无页面时明确写「不适用」。agent / CLI / 工具类产品使用文本交互原型，不硬画 UI。）\n\n- **涉及页面**：<是 / 否>\n- **原型链接**：<[Figma / Axure / Storybook / HTML / 仓库图片](URL)；无页面时写「不适用：无新增或修改页面」>\n- **覆盖范围**：<页面 / 对话框 / 交互；无页面写「不适用」>\n- **原型版本 / 日期**：<版本与日期>\n- **访问说明**：<谁能访问；agent 无法访问外部链接时附仓库内快照>\n- **覆盖状态**：<默认 / 空 / 加载 / 失败 / 权限不足>\n- **文字替代**：<关键结构、字段规则、主流程和异常状态在本文的位置>\n\n### 文本交互原型（无页面或工具交互时填写）\n\n（说明：用真实输入 / 输出文案表达反馈，标出当前状态、下一步和副作用；不适用就整块删除。）\n\n```text\n<状态 / 标题>\n【输入】<用户或 agent 的输入>\n【结果】<系统反馈>\n【下一步】<可执行动作与剩余路径>\n```\n\n### 图与清单设计\n\n（说明：图只辅助表达，必须有文字替代。页面列表写字段、排序、筛选、分页和状态；文档 / 结果清单写字段、排序、去重、空态和截断。）\n\n| 对象 | 必须说明 | 对应需求 / 原型 |\n|---|---|---|\n| <图 / 页面列表 / 结果清单> | <用途、字段、顺序、空态、异常态、文字替代> | <FR-x / 链接> |\n\n### 可用性验证\n\n- <用哪个任务、请哪类用户验证什么；记录结果和待改问题>\n\n## 功能需求\n\n（说明：先给清单，再逐条展开。清单给全貌，明细给行为——只列清单没有明细，等于没写需求。）\n\n### 需求清单\n\n（说明：一条需求 = 谁 + 什么场景 + 做什么 + 看到什么结果；优先级用 Must / Should / Could / Won't；验收判据要能被证伪。）\n\n| 编号 | 需求 | 优先级 | 验收判据 |\n|---|---|---|---|\n| FR-1 | <谁 + 场景 + 做什么 + 看到什么> | Must | <做什么 → 看到什么> |\n\n### 需求明细\n\n（说明：清单里每个编号都要有对应明细。**只有「描述 / 验收标准」必填**；其余三块按需——不需要就整块删掉，写了标题就必须有内容。）\n\n#### FR-1 <需求名>\n\n**优先级**：Must ｜ **角色**：<谁> ｜ **依赖**：<FR-x / 无>\n\n**描述**\n\n<一段话：这条需求做什么、边界在哪、为什么这么切。别复述清单行。>\n\n**验收标准**（Given / When / Then）\n\n- AC-1.1 Given <前置条件>，When <动作>，Then <可观察到的结果>。\n- AC-1.2 <…>\n\n**业务规则**（有多条规则 / 分支时才写；不需要就删掉这块）\n\n- BR-1.1 <一条可独立验证的规则；编号首段 = 所属 FR（FR-3 的规则是 BR-3.x）。>\n\n**异常与边界**（有失败 / 并发 / 空数据 / 超限时才写；不需要就删掉这块）\n\n- <本条特有的边界；系统级边界写进「边界与异常路径」，别重复。>\n\n**不在本期范围**（有明确排除时才写；不需要就删掉这块）\n\n- <本条明确不做的。>\n\n## 非功能需求\n\n（说明：性能 / 可靠性 / 安全 / 隐私 / 可观测性 / 可访问性 / 兼容 / 成本，给可量化的数。）\n\n| 编号 | 类别 | 要求 | 优先级 |\n|---|---|---|---|\n| NFR-1 | 性能 | <如 P95 < 200ms> | Must |\n\n## 边界与异常路径\n\n（说明：顺利路径之外怎么表现——空数据、超限、失败、并发、重试。确实不适用的写\"不适用：<理由>\"，不要留空。）\n\n- <异常 / 边界场景 → 期望表现>\n\n## 约束与依赖\n\n（说明：技术 / 时间 / 成本 / 合规约束；外部团队或系统的依赖，标清会不会阻塞开工。）\n\n| 类型 | 内容 | 是否阻塞 |\n|---|---|---|\n| 依赖 | <团队 / 系统 / 库> | <是 / 否> |\n\n## 风险与缓解\n\n（说明：会失败的地方、怎么兜；再补一行「最危险假设 + 验证方式」——如果这条假设错了，整件事不成立。）\n\n| 风险 | 概率 | 影响 | 缓解方案 |\n|---|---|---|---|\n| <风险> | 高 / 中 / 低 | 高 / 中 / 低 | <缓解方案> |\n| **最危险假设**：<如果它错了就不成立> | <高 / 中 / 低> | <高 / 中 / 低> | <用最便宜的方式先证伪> |\n\n## 常见问题\n\n（说明：Amazon PR-FAQ 的 FAQ 部分——客户会问什么、领导会问什么，包括你最难回答的那个。）\n\n### 客户 FAQ\n\n- **它替掉什么？** <现在的替代做法>\n- **它不做什么？** <明确排除>\n- **对现有工作流有什么影响？** <迁移 / 兼容 / 数据>\n\n### 内部 FAQ\n\n- **为什么是现在？** <时机>\n- **为什么由我们做？** <独特条件>\n- **最怕的问题是什么？** <最难回答的那个，别绕>\n- **要砍先砍哪块？** <范围优先级>\n\n## 备选方案\n\n（说明：认真考虑过、但没选的方案，各给一句\"为什么不选\"。没有就写\"无\"。）\n\n- <方案 B>：<为什么不选>\n\n## 发布与回滚\n\n（说明：怎么上、怎么灰度、出事怎么退；并写清可观测性与运维归属。纯文档或本地小改可写\"不涉及线上发布\"。）\n\n- **可观测性**：<日志 / 指标 / 告警阈值>\n- **运维归属**：<谁维护、支持入口>\n\n## 时间线\n\n（说明：里程碑要有日期和前置依赖，跟成功指标的时间窗对得上。）\n\n| 里程碑 | 时间 | 依赖 |\n|---|---|---|\n| <里程碑> | <日期> | <依赖> |\n\n## 开放问题\n\n（说明：每个问题给选项、负责人和截止——Google 的 Open Questions 要求。）\n\n| 问题 | 选项 | 负责人 | 截止 |\n|---|---|---|---|\n| <待定问题> | <备选项> | <谁> | <日期 / 已决> |\n\n## 附录\n\n（说明：调研、竞品、原型、相关文档；末尾补审批记录与变更历史。）\n\n- 相关文档：<链接>\n- 审批记录：<谁、何时批的>\n- 变更历史：<何时改了什么>\n",
    "example": "---\ntitle: 内容格式规则引擎 PRD\nstatus: approved\nowner: 插件组\nreviewers: 架构组、文档组\ncreated: 2026-10-14\nupdated: 2026-10-14\n---\n\n# 内容格式规则引擎 PRD\n\n## 摘要\n\n把「文档内容该长什么样」从写死的检查代码变成**可配置的规则数据**：项目在\n.dsh/file-format-specs/<type>/spec.yaml 里声明规则，插件在 write/edit 落盘后按规则校验，\n合规静默放行、不合规一次报全并给出目标模板。目标是把「agent 写完文档总差几节」从反复返工压到一次改对。\n\n## 发布公告\n\n**标题**：让每个项目自己定义「文档该写成什么样」\n\n**副标题**：面向用 DSH 写文档的项目——在项目里放一份 spec.yaml，agent 写的需求/PRD 自动按你的规范校验与纠偏，不合规不再靠人挑。\n\n**客户问题**：文档规范只能写进 prompt，模型想遵守但记不住；等评审时才发现缺章节、缺验收判据，同一份要返工两三次。\n\n**如释重负的一句话**：「改完 spec.yaml 就生效了，不用等插件发版，也不用再人肉挑格式。」\n\n## 背景与问题\n\n### 现状\n\n文档质量目前靠两件事兜：一是写死在插件里的几种检查（缺章节、缺 front-matter 字段），\n二是人工评审。项目想加一条自己的判据（例如「每条 FR 必须有验收判据」），必须改插件代码、重新构建。\n\n### 问题\n\n- 判据不可配置：项目特有的文档规范无法表达，只能写进 prompt 靠模型自觉；\n- 检查与修复脱节：只报「缺章节」不给目标形状，agent 知道缺什么、不知道改成什么样；\n- 误报漏报难定位：新增判据是代码改动，回归风险高，没人敢加。\n\n### 影响与证据\n\n- 试点项目 3 周内 PRD 因「缺验收标准」被打回：17 次 / 42 份；\n- 同一份需求平均要写 2.3 次才能过结构校验；\n- 项目方提出的 6 条自定义判据，因「要改插件」全部搁置。\n\n## 目标与非目标\n\n### 目标\n\n- 让项目**不改代码**就能声明文档结构判据，改 YAML 即生效；\n- 校验失败时给出**目标模板 + 差异清单**，agent 一轮改对；\n- 判据可增量启用，旧文档不被追溯。\n\n### 非目标\n\n- 不做自然语言质量评审（「这段话写得好不好」）——机器判不了，交给评审；\n- 不做跨文档全局一致性校验（本期只管单份文档的形状）；\n- 不替换宿主 write/edit，只在 post-execute 上挂校验。\n\n## 成功指标\n\n| 指标 | 基线 | 目标 | 时间窗 | 衡量方式 |\n|---|---|---|---|---|\n| agent 一次修复率 | 43% | ≥ 80% | 上线后 30 天 | 被 block 后下一次 write 即通过的占比 |\n| 单份需求结构化返工次数 | 2.3 | ≤ 1.2 | 上线后 60 天 | 台账统计 |\n| 自定义判据接入成本 | 改代码 + 发版 | 只改 YAML | 首版即可 | 试点项目实测 |\n| 单次校验耗时 P95 | 未测 | ≤ 50ms | 首版即可 | 插件日志 |\n\n## 目标用户与场景\n\n| 角色 | 场景 | 痛点 | 现状行为 | 期望行为 |\n|---|---|---|---|---|\n| 项目维护者 | 定义本项目的文档规范 | 判据写死在插件里，改不了 | 把要求写进 prompt | 在 spec.yaml 里声明规则 |\n| agent | 新建或修改文档 | 被拒后不知道目标形状 | 反复猜、反复写 | 按目标模板一次改对 |\n| 评审人 | 抽查文档 | 结构问题占用了评审时间 | 人工挑缺章节 | 机器先拦，评审只看内容 |\n\n## 用户旅程与流程设计\n\n### 参与者与触发条件\n\n- **参与者**：宿主 write/edit、插件、agent、项目维护者。\n- **触发条件**：write/edit 成功返回 after 全文。\n- **前置状态**：文件已经落盘；插件可按相对路径匹配项目 spec。\n- **结束状态**：合规时 accept 且零正文；warn/block 时返回差异与修复指引。block 只改变工具结果，不回滚已落盘内容。\n\n### 主流程（ASCII 图）\n\n```text\nwrite/edit 成功（after 已落盘）\n|\n+-- 未命中 spec --> accept，零正文\n|\n+-- 命中 spec\n    |\n    +-- spec 非法 --> 记录 warning，跳过该类型 --> accept\n    |\n    +-- spec 合法 --> derive + rules\n        |\n        +-- 函数异常：记一条错误，继续其它规则\n        |\n        +-- 聚合违规，并按 diff_mode 归责\n            |\n            +-- 无新增 error --> accept\n            |\n            +-- 有新增 error\n                |\n                +-- mode=off   --> accept\n                +-- mode=warn  --> accept + 警告与修复指引\n                +-- mode=block --> block + 差异清单 + 目标结构 + 重试信息\n                    |\n                    +-- 尚有重试预算\n                    |       agent 修复 --> write/edit --> 重新校验\n                    |\n                    +-- 重试耗尽\n                        |\n                        +-- on_exhausted=allow --> accept + 警告（仍可能不合规）\n                        +-- on_exhausted=block --> 保持 block，等待人工处理\n```\n\n### 状态与结果对照表\n\n| 场景 | 触发 / 操作 | 系统结果 | 用户反馈 | 下一步 |\n|---|---|---|---|---|\n| 未命中 spec | write/edit 成功 | accept；文件已写入 | 零正文 | 结束 |\n| 合规或 delta 后无新增 error | 校验完成 | accept；文件已写入 | 零正文或历史建议 | 结束 |\n| spec 非法 | 加载 spec | 跳过该类型；文件已写入 | warning 指向 spec，不伪报文档违规 | 维护者修 spec |\n| mode=warn 且有新增 error | 校验完成 | accept；文件可能仍有违规 | 警告 + 修复指引 | 决定是否修复 |\n| mode=block 且有新增 error | 校验完成 | block；文件已写入但不合规 | 差异 + 目标结构 + 剩余次数 | agent 修复 |\n| 重试耗尽且 allow | 再次提交仍不合规 | accept 放行；文件可能仍不合规 | 明确「已放行但未通过」 | 人工复查 |\n| 重试耗尽且 block | 再次提交仍不合规 | 保持 block；文件仍不合规 | 提示人工介入 | 人工处理 |\n\n### 异常与恢复路径\n\n- spec 缺失 → 不校验并静默放行；spec 非法 → 告警并提示维护者修复配置。\n- 自定义函数抛错或超时 → 记录函数执行失败，继续其它规则；依赖失败事实的规则按既定错误策略处理。\n- 同一 after 重复提交 → 提示「内容未变，仍不符合」，避免无效重试。\n- 重试耗尽 → 明确区分「零 error 通过」与「on_exhausted=allow 放行」，后者仍须人工复查。\n\n### 流程与需求追踪\n\n| 流程节点 | 对应需求 | 验收判据 |\n|---|---|---|\n| spec 加载与热更新 | FR-1 | AC-1.1 / AC-1.2 |\n| 条件求值与派生 | FR-2 / FR-3 | AC-2.1 / AC-3.1 / AC-3.2 |\n| 内置原语与自定义函数 | FR-4 / FR-5 | AC-4.1 / AC-5.1 |\n| delta 归责 | NFR-6 | before/after 对照测试 |\n| 差异、模板与重试反馈 | FR-6 / NFR-5 | AC-6.1 / AC-6.2 / 结构化日志 |\n\n## 原型与交互说明\n\n- **涉及页面**：否。\n- **原型链接**：不适用——本产品无新增或修改页面。\n- **覆盖范围**：agent 在 write/edit 后接收的 accept / warn / block 文本反馈。\n- **原型版本 / 日期**：文本原型 v1 / 2026-10-14。\n- **访问说明**：原型内联在本文件，无外部链接依赖。\n- **覆盖状态**：静默通过、普通 block、历史违规 delta、spec 非法、重试耗尽。\n- **文字替代**：流程见上一节；反馈字段与异常语义见 FR-6 和「边界与异常路径」。\n\n### 文本交互原型\n\n```text\n⛔ 文件已写入，但内容校验未通过（第 1/3 次）\n\n【本次新增问题】\n1. [sections] 缺章节「常见问题」\n   建议位置：「风险与缓解」之后\n\n【历史问题】0 项\n\n【目标结构】\n（小模板在此内联；大模板给路径与必要节清单）\n\n【填写参考】\n.dsh/file-format-specs/prd/example.md\n\n【下一步】\n用 write 或 edit 修改同一文件；还剩 2 次修复机会。\n```\n\n### 图与清单设计\n\n| 对象 | 必须说明 | 对应需求 / 原型 |\n|---|---|---|\n| 主流程 ASCII 图 | 分支、顺序、异常出口；状态表作为文字替代 | FR-1～FR-6 / 上一节 |\n| 违规清单 | rule id、严重度、新增 / 历史、行号或插入锚点、问题、修复建议、排序与去重 | FR-6 / 文本交互原型 |\n| 需求清单 | 稳定 FR 编号、优先级、验收判据、明细追踪 | FR-1～FR-6 / 需求清单 |\n\n### 可用性验证\n\n- 维护者任务：不看实现文档，新增「每条 FR 必须有验收判据」规则；记录首次配置成功率与卡点。\n- agent 任务：只依据 block 指引修复缺章节；记录下一次 write/edit 零 error 的比例，以及是否理解文件已经落盘。\n- 评审任务：区分新增 / 历史违规、配置错误 / 文档违规、真正通过 / 重试耗尽放行；记录误读点。\n\n## 功能需求\n\n### 需求清单\n\n| 编号 | 需求 | 优先级 | 验收判据 |\n|---|---|---|---|\n| FR-1 | 维护者在类型目录的 spec.yaml 声明规则，无需改插件即可生效 | Must | 改 spec.yaml 保存后，下次写文档即按新规则校验，无需重启 |\n| FR-2 | 引擎以「事实 + 条件树」求值：all/any/not/path/each/exists/count/fn | Must | 用 each + where 表达「每个 H2 必须带 serves」，违反时报出对应行号 |\n| FR-3 | 支持前向链 derive，把重复计算变成事实 | Should | 派生 requirementCount 后，规则可直接用 [requirementCount ≥ 1] 判定 |\n| FR-4 | 内置原语（sectionsRequired/tableRequired/ids/idDetails 等）以 fn 形式调用 | Must | { fn: sectionsRequired, args: [{headings:[…]}] } 缺节即报 |\n| FR-5 | 允许在 functions 里写 expr/script 自定义判据，沙箱加超时 | Should | 死循环脚本被 1s 超时截断并报一条错误，不影响其它规则 |\n| FR-6 | 校验失败时输出目标模板与差异清单 | Must | 没有模板时按规则反推目标结构，block 文本含「目标结构」小节 |\n\n### 需求明细\n\n#### FR-1 spec.yaml 声明即生效\n\n**优先级**：Must ｜ **角色**：项目维护者 ｜ **依赖**：无\n\n**描述**\n\n规则以项目内的文件为载体：每个类型目录一份 spec.yaml，插件校验时按目录读取并缓存。用户改文件即生效，插件不需要重新发版。\n\n**业务规则**\n\n- BR-1.1 每个类型目录（目录名即类型名）下一份 spec.yaml，含 match 与 rules。\n- BR-1.2 rules/derive/functions 三块都可选，缺省即无对应判据。\n- BR-1.3 缓存按 spec.yaml 与 template.md/example.md 的 mtime 失效。\n\n**验收标准**（Given / When / Then）\n\n- AC-1.1 Given 已有一个类型目录，When 修改其 spec.yaml 并保存，Then 下一次 write/edit 按新规则校验，无需重启。\n- AC-1.2 Given spec.yaml 语法非法，When 触发校验，Then 记一条 warning 并跳过该类型，其它类型照常。\n\n**异常与边界**\n\n- spec.yaml 缺失 → 该类型完全不受约束，静默放行。\n\n**不在本期范围**\n\n- 不做 spec 的可视化编辑器，不做 IDE 插件。\n\n#### FR-2 条件树求值\n\n**优先级**：Must ｜ **角色**：项目维护者 ｜ **依赖**：FR-1\n\n**描述**\n\n引擎把文档铺成事实集合，条件树在其上递归求值。条件分四类：组合子、量词、叶子、函数调用。\n\n**业务规则**\n\n- BR-2.1 组合子语义：all 全过才过、any 一过即过、not 取反。\n- BR-2.2 量词（each/exists/count）把作用域重绑到元素，元素行号冒泡到违规。\n- BR-2.3 未知算子按 false；无法识别的条件报一条错误，绝不崩。\n\n**验收标准**（Given / When / Then）\n\n- AC-2.1 Given 一份 H2 缺 serves 的文档，When 跑 each + where + require，Then 报出缺标注的具体行号。\n- AC-2.2 Given 条件里写了未知算子，When 求值，Then 该条判 false 且不抛异常。\n\n**异常与边界**\n\n- path 指向不存在的事实 → 返回 undefined；each/exists 目标不是数组 → 报一条错误。\n\n**不在本期范围**\n\n- 不做短路求值与缓存优化。\n\n#### FR-3 前向链派生\n\n**优先级**：Should ｜ **角色**：项目维护者 ｜ **依赖**：FR-2\n\n**描述**\n\n规则求值前先跑 derive，把重复计算固化成事实；后一条能看见前一条写入的事实。\n\n**业务规则**\n\n- BR-3.1 derive 支持 fn/expr/script/value 四种来源，按声明顺序执行。\n- BR-3.2 派生结果写入事实集，规则用 path 读取。\n\n**验收标准**（Given / When / Then）\n\n- AC-3.1 Given 声明 requirementCount = countIds([\"FR\"])，Then 规则可直接写 path: requirementCount, op: gte。\n- AC-3.2 Given 某条 derive 的函数抛错，Then 该条记一个错误，其余规则照常。\n\n**异常与边界**\n\n- fact 名为空 → 该条跳过；重复派生同名事实 → 后者覆盖前者。\n\n**不在本期范围**\n\n- 不做跨文档派生。\n\n#### FR-4 内置原语\n\n**优先级**：Must ｜ **角色**：项目维护者 ｜ **依赖**：FR-2\n\n**描述**\n\n常见结构判据以纯函数内置，注册成引擎函数供 fn 调用。参数是一个对象，结构类判据按归一化节名精确匹配、只认 H2。\n\n**业务规则**\n\n- BR-4.1 原语签名统一为 (doc, params)，yaml 里的 args[0] 即 params。\n- BR-4.2 结构类原语按归一化节名精确匹配（去编号 / 括注 / serves）。\n- BR-4.3 idDetails 校验「清单编号 ↔ 明细标题」，并可强制明细小节。\n\n**验收标准**（Given / When / Then）\n\n- AC-4.1 Given 文档缺一节，When 跑 sectionsRequired，Then 报「缺章节」并给出行号。\n- AC-4.2 Given 清单有 FR-7 但无对应明细，When 跑 idDetails，Then 报「缺对应明细标题」。\n\n**异常与边界**\n\n- 参数缺省时按最小语义（如表头为空则只找表）；节名不匹配即报缺失。\n\n**不在本期范围**\n\n- 不做原语的插件外注册。\n\n#### FR-5 自定义函数沙箱\n\n**优先级**：Should ｜ **角色**：项目维护者 ｜ **依赖**：FR-2\n\n**描述**\n\n内置覆盖不到的判据用 expr/script 补。脚本在 node:vm 干净上下文执行，只注入白名单全局，默认 1s 超时。\n\n**业务规则**\n\n- BR-5.1 expr 返回布尔：为假则报 rule 的 message。\n- BR-5.2 script 返回值归一化：undefined/null/true/[] 视为通过，string/对象/数组视为违规。\n- BR-5.3 抛错只记一条「函数执行失败」，不阻断其它规则。\n\n**验收标准**（Given / When / Then）\n\n- AC-5.1 Given 脚本 while(true){}，When 执行，Then 1s 超时截断且只产出一条错误。\n- AC-5.2 Given script 返回 [{message, line}]，Then 拆成带行号的违规。\n\n**异常与边界**\n\n- 访问白名单外的全局 → 抛错并记一条错误。\n\n**不在本期范围**\n\n- 不支持异步脚本。\n\n#### FR-6 目标模板与差异清单\n\n**优先级**：Must ｜ **角色**：agent ｜ **依赖**：FR-4\n\n**描述**\n\nblock 时把「改什么」和「改成什么样」一起给出：目标结构优先用模板文件，其次从规则反推骨架，示例只给路径。\n\n**业务规则**\n\n- BR-6.1 目标优先级：template.md 全文 > 规则反推骨架 > 只给差异清单。\n- BR-6.2 example.md 只输出路径指针，不内联正文。\n- BR-6.3 一次报全所有新增违规，不第一条就停。\n\n**验收标准**（Given / When / Then）\n\n- AC-6.1 Given 一份缺章节的 PRD，Then block 文本含「【目标结构】」与缺失章节名。\n- AC-6.2 Given 类型目录有 example.md，Then block 文本含「【填写参考】<路径>」。\n\n**异常与边界**\n\n- 模板缺失 → 退化为骨架；示例缺失 → 不打指针；推不出结构 → 只给差异清单。\n\n**不在本期范围**\n\n- 不做多候选目标的 A/B 推荐。\n\n## 非功能需求\n\n| 编号 | 类别 | 要求 | 优先级 |\n|---|---|---|---|\n| NFR-1 | 性能 | 单次校验 P95 ≤ 50ms（1000 行文档） | Must |\n| NFR-2 | 可靠性 | 单份 spec 非法只跳过并告警，不影响其它类型校验 | Must |\n| NFR-3 | 安全 | 用户脚本在 node:vm 白名单上下文执行，默认 1s 超时 | Must |\n| NFR-4 | 隐私 | 校验只读 write/edit 结果里的 after 全文，不落盘、不外发、不留存 | Must |\n| NFR-5 | 可观测性 | 每次 block 记一条结构化日志（spec 名 / 规则 id / 违规数），便于统计误报 | Should |\n| NFR-6 | 兼容 | 旧文档不追溯：diff_mode=delta 只拦本次新增的违规 | Should |\n\n## 边界与异常路径\n\n- 目录里没有对应类型的 spec：不校验，静默放行（只拦登记过的类型）；\n- spec.yaml 残缺或非法：记一条 warning 并跳过该类型，其它类型照常；\n- 模板文件缺失：不报错，退化为从规则反推目标结构骨架；\n- 匹配到多个 spec：按 priority 降序取首个命中；\n- 自定义脚本抛错：只产出一条「函数执行失败」，不阻断其余规则。\n\n## 约束与依赖\n\n| 类型 | 内容 | 是否阻塞 |\n|---|---|---|\n| 依赖 | 宿主 tools/post-execute 钩子与 PostToolDecision | 是 |\n| 依赖 | node:vm（脚本沙箱） | 否 |\n| 约束 | 校验只发生在 write/edit 成功之后（拿 after 全文） | 是 |\n| 约束 | 不能修改工具入参（宿主冻结 arguments） | 是 |\n\n## 风险与缓解\n\n| 风险 | 概率 | 影响 | 缓解方案 |\n|---|---|---|---|\n| 规则写错导致误拦 | 中 | 高 | 非法 spec 跳过，配合 file_check 巡检与示例零违规守护 |\n| 模板与规则漂移 | 中 | 中 | 模板自身必须通过本 spec 的守护测试 |\n| 自定义脚本写坏（死循环或抛错） | 低 | 中 | vm 白名单加 1s 超时，单条错误隔离 |\n| 打回文本过长 | 中 | 低 | 小模板内联，大模板给地址与节清单，并始终附填写参考指针 |\n| **最危险假设**：项目方其实不愿维护 spec.yaml，宁可继续写 prompt | 中 | 高 | 试点 2 周内自建 spec 的项目数 ≥ 2；达不到就先做内置默认规范，再谈自定义 |\n\n## 常见问题\n\n### 客户 FAQ\n\n- **它替掉什么？** 替掉写进 prompt 的格式要求，以及评审阶段人肉挑缺章节。\n- **它不做什么？** 不评内容好坏、不做跨文档一致性、不替换宿主 write/edit。\n- **对现有工作流有什么影响？** 默认 diff_mode=delta，只拦本次新增的违规；存量文档不被追溯，无需迁移。\n\n### 内部 FAQ\n\n- **为什么是现在？** 试点 3 周 17 次格式打回，评审时间被结构问题吃掉，6 条自定义判据全被「要改插件」卡住。\n- **为什么由插件层做？** 写文档的是 agent，校验必须挂在落盘链路上；prompt 约束无法机械验证。\n- **最怕的问题是什么？** 项目方不愿维护 YAML。对策见风险表的最危险假设行。\n- **要砍先砍哪块？** 先砍 functions 里的 script 逃生舱（保留 expr），再砍示例内联；核心只留声明式规则 + 结构原语。\n\n## 备选方案\n\n- 继续用写死的检查代码：接入新判据要改插件、发版，正是本期要解决的成本，不选；\n- 纯 prompt 约束：模型自觉性不可靠，且无法机械验证，不选；\n- 正则整篇匹配：表达不了「每个 H2 都要有 serves」这类结构判据，不选。\n\n## 发布与回滚\n\n按 workspace 灰度：先在试点项目用 warn 模式观察误报，再切成 block。\n回滚只需把对应 spec 的 mode 改为 off，无需发版。插件本体升级走常规 bundle 安装。\n\n- **可观测性**：每次 block 记结构化日志（spec / 规则 id / 违规数 / 耗时）；误报率超过 5% 触发告警并自动降级为 warn。\n- **运维归属**：spec.yaml 由项目方维护；插件组负责引擎与内置原语；支持入口 = 插件仓库 issue。\n\n## 时间线\n\n| 里程碑 | 时间 | 依赖 |\n|---|---|---|\n| PRD 批准 | 2026-10-14 | 本文件 |\n| 引擎可用（规则 / derive / 函数） | 2026-10-20 | 宿主 post-execute 钩子 |\n| 试点 warn | 2026-10-27 | 示例规范 + 守护测试 |\n| 试点切 block | 2026-11-10 | warn 期误报率 < 5% |\n| 全量 | 2026-11-24 | 试点复盘通过 |\n\n## 开放问题\n\n| 问题 | 选项 | 负责人 | 截止 |\n|---|---|---|---|\n| 大模板是否改为「指针 + 节清单」 | 全文内联 / 超阈值转指针 | 插件组 | 2026-10-30 |\n| example.md 是否内联进打回文本 | 内联 / 只给路径 | 插件组 | 已决：只给路径 |\n| 跨文档一致性校验是否进下一期 | 进 / 不进 | 架构组 | 2026-11-15 |\n\n## 附录\n\n- 设计文档：docs/content-validation-design.md\n- 模板规范：docs/template-authoring.md\n- 规则引擎实现：src/content-format/rules/\n- 审批记录：插件组 + 架构组于 2026-10-14 批准；文档组复核格式\n- 变更历史：2026-10-14 初稿；同日按发布公告 / FAQ / 时间线补 PR-FAQ 结构\n"
  },
  "requirement": {
    "spec": "# .dsh/file-format-specs/requirement/spec.yaml —— 需求文档（需求池 + 验证记录）格式规范\n# 定位：**PRD 的上游**。PRD 回答「选中的这个功能做什么、为什么现在做」，\n# 本文回答「这些诉求本身成立吗、凭什么排在前面、哪些已经决定不做」。\n# 结构取自四条主线的交集：\n#   Wiegers ：需求开发（获取 → 分析 → 规格 → 验证）+ 需求属性（来源 / 理由 / 优先级 / 状态）+ 基线变更控制\n#   Cagan   ：机会评估——先用最便宜的方式证伪价值，未验证的诉求不许进 PRD\n#   Amazon  ：从客户倒推——每条需求都要有原始诉求与证据；写不出证据的，那不是需求，是偏好\n#   Google  ：排序要有依据、待定项要有负责人与截止（Open Questions）\next: md\npriority: 70\n# 关键词包含匹配：requirement 能命中 requirement.md / 需求文档.md / 需求池.md\n# 「产品需求」故意不在这里声明——它归 prd（priority 90）先命中，避免抢单。\nmatch:\n  - \"requirement\"\n  - \"需求文档\"\n  - \"需求池\"\nmode: block\ndiff_mode: delta\nmax_attempts: 3\non_exhausted: allow\n\n# —— 规则引擎 ——\nderive:\n  - fact: requirementCount        # 全文数 R-1 这类编号（含表格单元格）\n    fn: countIds\n    args: [[\"R\"]]\n\nfunctions:\n  hasOwner:\n    expr: \"!!(frontmatter.owner || frontmatter.owner_team)\"\n\n  noPlaceholder:\n    expr: \"!/TODO|TBD|待补充/.test(text)\"\n\n  # 动态函数：需求清单的「优先级」列必须是 MoSCoW 词表。\n  # 「高 / 中 / 低」既无法机械排序，也无法和 PRD 的优先级对齐——出现即打回。\n  priorityVocabulary:\n    script: |\n      const t = doc.tables.find(x => x.header.join('|').includes('需求陈述') && x.header.join('|').includes('优先级'))\n      if (!t) return []\n      const i = t.header.findIndex(h => h.includes('优先级'))\n      const ok = ['Must', 'Should', 'Could', \"Won't\"]\n      return t.rows.flatMap((row, n) => {\n        const v = String(row[i] ?? '').trim()\n        return ok.includes(v) ? [] : [{\n          message: '需求清单第 ' + (n + 1) + ' 行优先级「' + v + '」不在 MoSCoW 词表（Must / Should / Could / Won\\'t）',\n          line: t.line,\n          key: 'prio:' + n,\n        }]\n      })\n\nrules:\n  - id: fm\n    assert:\n      fn: frontmatterRequired\n      args:\n        - keys: [title, status]\n  - id: status-enum\n    assert: { fn: frontmatterEnum, args: [{ key: status, values: [draft, review, approved, superseded] }] }\n\n  # 必备章节，按需求开发的推进顺序（结构节只认 H2）\n  - id: sections\n    assert:\n      fn: sectionsRequired\n      args:\n        - order: true\n          headings:\n            - 摘要\n            - 背景与来源\n            - 干系人与角色\n            - 待解问题\n            - 假设与风险\n            - 需求清单\n            - 需求明细\n            - 优先级与排序\n            - 需求验证\n            - 变更控制\n            - 与 PRD 的映射\n            - 开放问题\n            - 附录\n\n  # 关键表格：缺表 / 缺列 / 行数不足都会被打回\n  # Wiegers：先有问题，再有需求——问题清单在前\n  - id: problem-table\n    assert: { fn: tableRequired, args: [{ under: 待解问题, header: [问题, 证据, 影响, 谁受影响] }] }\n  # Cagan：最危险假设必须能被证伪\n  - id: assumption-table\n    assert: { fn: tableRequired, args: [{ under: 假设与风险, header: [假设, 如果错了会怎样, 证伪方式, 结论] }] }\n  - id: stakeholder-table\n    assert: { fn: tableRequired, args: [{ under: 干系人与角色, header: [角色, 关注点, 影响程度, 决策权] }] }\n  # 需求清单：编号 + 陈述 + 类型 + 优先级 + 状态（状态含被拒与延期，需求池不只装活下来的）\n  - id: requirement-table\n    assert: { fn: tableRequired, args: [{ under: 需求清单, header: [编号, 需求陈述, 类型, 优先级, 状态] }] }\n  # 每个 R-x 都要有明细：描述 / 来源与证据 / 验收判据 / 优先级理由 必填\n  - id: requirement-details\n    assert: { fn: idDetails, args: [{ under: 需求清单, fields: [描述, 来源与证据, 验收判据, 优先级理由], optional: [依赖与假设, 不做的后果] }] }\n  - id: ranking-table\n    assert: { fn: tableRequired, args: [{ under: 优先级与排序, header: [排序方法, 判据, 本轮结论] }] }\n  # Wiegers 的需求验证：每条进来的需求都要有验证方式与结论\n  - id: validation-table\n    assert: { fn: tableRequired, args: [{ under: 需求验证, header: [需求编号, 验证方式, 结论, 验证人] }] }\n  - id: change-table\n    assert: { fn: tableRequired, args: [{ under: 变更控制, header: [日期, 变更, 谁提的, 决策, 影响] }] }\n  # 追溯接缝：需求池 → PRD（这张表就是两份文档之间的链）\n  - id: prd-mapping-table\n    assert: { fn: tableRequired, args: [{ under: 与 PRD 的映射, header: [需求编号, PRD 需求编号, 状态] }] }\n  - id: open-questions\n    assert: { fn: tableRequired, args: [{ under: 开放问题, header: [问题, 选项, 负责人, 截止] }] }\n\n  - id: has-owner\n    when: { path: \"frontmatter.status\", op: \"notEmpty\" }   # 守卫：只对有 status 的文档生效\n    assert: { fn: \"hasOwner\", message: \"需求文档必须有 owner 或 owner_team\" }\n    priority: 10\n\n  - id: at-least-one-requirement\n    assert: { path: \"requirementCount\", op: \"gte\", value: 1, message: \"需求清单至少一条编号（R-1…）\" }\n\n  - id: priority-vocabulary\n    assert: { fn: priorityVocabulary }\n\n  - id: no-placeholder\n    severity: warning\n    assert: { fn: noPlaceholder, message: \"文档里不能留 TODO / TBD / 待补充\" }\n",
    "template": "---\ntitle: <需求池名 / 项目名> 需求文档\nstatus: draft\nowner: <需求负责人>\nreviewers: <评审人>\nsources: <回访 / 工单 / 访谈 / 数据的来源说明>\ncreated: <YYYY-MM-DD>\nupdated: <YYYY-MM-DD>\n---\n\n# <需求池名 / 项目名> 需求文档\n\n（说明：本文件是 **PRD 的上游**。PRD 回答「选中的这个功能做什么」，本文回答「这些诉求本身成立吗、凭什么排在前面、哪些已经决定不做」。**需求池不只装活下来的需求**——被拒的、延期的、合并的都要在这里留痕，否则三个月后没人知道为什么没做。编号约定：`R-x`（本文）→ `FR-x` / `NFR-x`（PRD）。）\n\n## 摘要\n\n（说明：3 行以内回答三问——这批需求要解决什么 / 谁提的、有什么证据 / 这一轮决定做什么、不做什么。）\n\n- **要解决什么**：<一句话>\n- **来源与证据强度**：<谁提的；是访谈、工单还是数据>\n- **本轮结论**：<进 PRD 的几条 / 被拒的几条 / 延期的几条>\n\n## 背景与来源\n\n（说明：Amazon 的「从客户倒推」——先讲这批诉求从哪来、在什么场景下产生，再谈怎么解。不要写「用户希望更好用」这类无法证伪的话。）\n\n- **收集方式**：<访谈 / 工单 / 数据回访 / 竞品观察；时间范围>\n- **样本**：<几条访谈、多少工单、覆盖哪些角色>\n- **原始记录**：<链接或附件路径>\n\n## 干系人与角色\n\n（说明：谁提的、谁受影响、谁有决策权。三者常常不是同一批人——混淆它们会让优先级排错。）\n\n| 角色 | 关注点 | 影响程度 | 决策权 |\n|---|---|---|---|\n| <角色> | <他最在意什么> | 高 / 中 / 低 | 决策 / 建议 / 知情 |\n\n## 待解问题\n\n（说明：Wiegers 的顺序是「先问题，后需求」——需求是对问题的回答。问题写不清，需求一定是拍脑袋。）\n\n| 问题 | 证据 | 影响 | 谁受影响 |\n|---|---|---|---|\n| <问题陈述> | <工单数 / 访谈原话 / 数据> | <不解决的代价> | <角色> |\n\n## 假设与风险\n\n（说明：Cagan 的机会评估——最危险的那条假设必须能被最便宜的方式证伪；「结论」列写实际验证结果，没验证就写「未验证」。）\n\n| 假设 | 如果错了会怎样 | 证伪方式 | 结论 |\n|---|---|---|---|\n| <如果…那么…因为…> | <整件事是否还成立> | <访谈 / 原型 / 数据 / 试用> | 未验证 / 成立 / 已证伪 |\n\n## 需求清单\n\n（说明：清单给全貌，明细给依据。优先级只用 MoSCoW 四个值——「高 / 中 / 低」无法机械排序，也会和 PRD 对不上。状态必须包含被拒与延期的项。）\n\n| 编号 | 需求陈述 | 类型 | 优先级 | 状态 |\n|---|---|---|---|---|\n| R-1 | <谁 + 什么场景 + 想要什么> | 功能 / 质量属性 / 约束 | Must | 待验证 / 已验证 / 已进 PRD / 已拒 / 已延期 / 已合并 |\n\n## 需求明细\n\n（说明：清单里每个编号都要有对应明细。**只有「描述 / 来源与证据 / 验收判据 / 优先级理由」必填**；其余两块按需——不需要就整块删掉，写了标题就必须有内容。）\n\n#### R-1 <需求名>\n\n**描述**\n\n<这条需求要什么、边界在哪、为什么这么切。别复述清单行。>\n\n**来源与证据**\n\n<谁提的、原话或工单号、出现频次；找不到证据就写「无直接证据，来自推测」——那它就不该是 Must。>\n\n**验收判据**\n\n<怎么算满足了：可观察的结果，能被测试或数据证伪。>\n\n**优先级理由**\n\n<为什么是 Must 而不是 Should：不做会怎样、谁会被卡住、有没有更便宜的替代。>\n\n**依赖与假设**（有前置条件时才写；不需要就删掉这块）\n\n<依赖哪条需求 / 哪个团队 / 哪个前提成立。>\n\n**不做的后果**（这条需求有明确代价时才写；不需要就删掉这块）\n\n<不做会持续损失什么。>\n\n## 优先级与排序\n\n（说明：排序方法要写出来，不能只给结果。MoSCoW 之外常用的还有 WSJF / RICE——选一种并写清判据，下一轮换方法时才能解释差异。）\n\n| 排序方法 | 判据 | 本轮结论 |\n|---|---|---|\n| <MoSCoW / WSJF / RICE> | <用什么算的> | <排在最前面的是哪几条、为什么> |\n\n## 需求验证\n\n（说明：Wiegers 的需求验证——每条进入 PRD 的需求都要有验证方式与**结论**；只写「已评审」不算验证，要写清用什么核对过。）\n\n| 需求编号 | 验证方式 | 结论 | 验证人 |\n|---|---|---|---|\n| R-1 | <访谈回访 / 原型测试 / 数据核对 / 走查> | 成立 / 需修改 / 已证伪 | <谁> |\n\n## 变更控制\n\n（说明：需求基线一旦定下，变更要留痕——谁提的、怎么决策的、影响到哪些下游文档（PRD / 设计 / 指标）。口头改需求是这份文档最常见的失效方式。）\n\n- **基线**：<本文件 v1.0 定于 YYYY-MM-DD；基线之后的新增一律走本表>\n\n| 日期 | 变更 | 谁提的 | 决策 | 影响 |\n|---|---|---|---|---|\n| <YYYY-MM-DD> | <新增 / 修改 / 撤销哪条 R-x> | <谁> | 接受 / 拒绝 / 延期 | <影响哪些 FR-x / 设计 / 指标> |\n\n## 与 PRD 的映射\n\n（说明：这张表就是需求池与 PRD 之间的链。一个 R-x 可以拆到多条 FR-x，多条 R-x 也可以合成一条；**被拒的 R-x 也要出现在这里**并在 PRD 需求编号列写「无（见非目标）」。）\n\n| 需求编号 | PRD 需求编号 | 状态 |\n|---|---|---|\n| R-1 | <FR-1 / 多条 / 无（见非目标）> | 已覆盖 / 部分覆盖 / 未覆盖 / 已拒 |\n\n## 开放问题\n\n（说明：每个问题给选项、负责人、截止。截止到了还没有结论，就写「已决 + 结论」，不要留着当装饰。）\n\n| 问题 | 选项 | 负责人 | 截止 |\n|---|---|---|---|\n| <待定问题> | <备选项> | <谁> | <日期 / 已决：结论> |\n\n## 附录\n\n（说明：访谈记录、工单清单、竞品观察、数据截图、相关文档。需求池定稿后冻结为基线，后续变更走「变更控制」。）\n\n- **原始记录**：<链接>\n- **相关文档**：<PRD / 上一轮需求池 / 调研报告>\n- **变更历史**：<何时改了什么、为什么>\n",
    "example": "---\ntitle: 文件规范插件 需求池\nstatus: approved\nowner: 产品组\nreviewers: 插件组、架构组、文档组\nsources: 试点项目回访（3 人访谈）+ 42 份文档返工记录 + 6 条搁置判据清单\ncreated: 2026-10-08\nupdated: 2026-10-14\n---\n\n# 文件规范插件 需求池\n\n## 摘要\n\n- **要解决什么**：项目想约束文档结构，但判据写死在插件代码里，只能退化成 prompt 里的一句叮嘱。\n- **来源与证据强度**：3 人访谈 + 42 份文档返工记录 + 6 条被「要改插件」挡住的判据清单，证据集中且可复核。\n- **本轮结论**：8 条需求中 6 条已进 PRD（R-1～R-6），1 条明确拒绝（R-7），1 条延期（R-8）。\n\n## 背景与来源\n\n- **收集方式**：试点项目回访（半结构化访谈 3 人，各 45 分钟）+ 台账统计（3 周内 42 份文档的返工次数）+ 需求方自己列的判据清单（6 条）。时间范围 2026-09-22 ～ 2026-10-07。\n- **样本**：3 名项目维护者、2 名评审人、1 名插件维护者；覆盖 2 个试点项目。\n- **原始记录**：访谈纪要 `docs/notes/2026-10-pilot-interviews.md`；返工台账见 PRD 示例的「影响与证据」一节。\n\n## 干系人与角色\n\n| 角色 | 关注点 | 影响程度 | 决策权 |\n|---|---|---|---|\n| 项目维护者 | 判据能不能改成自己的；改完成本多高 | 高 | 决策（是否在本项目启用） |\n| agent | 被打回后能不能一轮改对 | 高 | 建议（反馈可读性） |\n| 评审人 | 评审时间别被结构问题吃掉 | 中 | 建议 |\n| 插件组 | 引擎抽象是否值得；误报是否可控 | 高 | 决策（是否实现） |\n\n## 待解问题\n\n| 问题 | 证据 | 影响 | 谁受影响 |\n|---|---|---|---|\n| 项目特有的文档规范无处表达 | 6 条判据全部因「要改插件」搁置 | 规范只能靠 prompt，无法机械验证 | 项目维护者、评审人 |\n| 校验只报缺什么、不报改成什么样 | 同一份需求平均写 2.3 次；PRD 因缺验收标准被打回 17 次 / 42 份 | agent 反复试错，上下文与时间被吃掉 | agent、评审人 |\n| 新增判据＝改代码＋发版 | 判据改动需要构建、安装、重启，回归风险高 | 没人敢加判据，规范长期停留在初始版本 | 插件组、项目维护者 |\n| 存量文档结构不齐 | 试点已有 200+ 份存量文档，其中约三成缺必备章节 | 若全量追溯会产生上千条历史违规，直接压垮新机制 | 项目维护者 |\n\n## 假设与风险\n\n| 假设 | 如果错了会怎样 | 证伪方式 | 结论 |\n|---|---|---|---|\n| 如果判据可配置，那么项目方会自己维护 spec.yaml，因为改 YAML 比改代码便宜 | 整件事的价值归零——产品退化成又多一份没人维护的配置 | 2 周内统计「自建 spec 的项目数 ≥ 2」 | 未验证 |\n| 如果打回文本给出目标形状，那么 agent 一次修复率会从 43% 提到 80% 以上 | 反馈链路白做，agent 仍靠猜 | 6 份真实被打回文档做修复演练，记录下一次 write 即零 error 的比例 | 未验证 |\n| 如果判据只判机器能证伪的结构事实，那么误报率会低于 5% | 误报侵蚀信任，维护者会直接把 mode 关掉 | 试点 warn 期统计误报率 | 未验证 |\n| 如果校验只读落盘后的全文、不写文件，那么在插件里做校验不会影响宿主写入 | 需要改成独立进程或异步校验，架构与里程碑都要重排 | 集成测试覆盖 accept / block / 放行三态 | 成立 |\n\n## 需求清单\n\n| 编号 | 需求陈述 | 类型 | 优先级 | 状态 |\n|---|---|---|---|---|\n| R-1 | 项目维护者要能自己声明本项目的文档判据，不必改插件代码或等发版 | 约束 | Must | 已进 PRD |\n| R-2 | 判据要能表达跨行、跨节的结构约束（如「每个 H2 都要带标注」「清单编号必须在明细里出现」） | 功能 | Must | 已进 PRD |\n| R-3 | 同一条判据在多处重复计算时应该能复用，而不是各写一遍 | 约束 | Should | 已进 PRD |\n| R-4 | 内置判据覆盖不到时，项目能自己写补充判据 | 功能 | Should | 已进 PRD |\n| R-5 | agent 被打回后必须知道「改成什么形状」，而不只是「缺了什么」 | 质量属性 | Must | 已进 PRD |\n| R-6 | 存量文档不该被追溯，只拦本次新增的问题 | 约束 | Must | 已进 PRD |\n| R-7 | 希望机器也评「这段话写得好不好、清不清楚」 | 功能 | Won't | 已拒 |\n| R-8 | PRD 的指标名与指标方案必须一一对应（跨文档一致性） | 功能 | Could | 已延期 |\n\n## 需求明细\n\n#### R-1 判据可配置\n\n**描述**\n\n项目在自己的工作区里放一份 spec.yaml 声明文档结构与内容判据，插件按它校验；新增或修改判据只改 YAML，不碰插件代码、不需要发版或重启会话。\n\n**来源与证据**\n\n维护者访谈 3/3 提到「判据改不了」；需求方给出的 6 条自定义判据全部标注理由「要改插件，先搁置」，清单见访谈纪要附录 B。\n\n**验收判据**\n\n改 spec.yaml 并保存后，下一次 write/edit 即按新规则校验（无需重启）；一份非法 spec 只影响它自己那个类型，其它类型照常校验。\n\n**优先级理由**\n\nMust：不做则产品价值为零——项目只能用 prompt 表达规范，而 prompt 无法机械验证。它是 R-2 / R-4 的载体。\n\n#### R-2 跨行跨节的结构判据\n\n**描述**\n\n判据要能表达「每个 H2 都必须带 serves 标注」「清单里的每个编号都必须在明细里出现」这类跨行、跨节的约束，并且报错要能定位到行号。\n\n**来源与证据**\n\n维护者列出的 6 条判据里 5 条属结构类（章节齐全、编号连续、表格列齐、章节标注、清单与明细对齐）；访谈中明确表示「正则整篇匹配做不到『每一个』」。\n\n**验收判据**\n\n用条件树（each + where）或内置原语表达「每个 H2 必须带 serves」，违反时报出对应行号；清单有编号但缺明细时能被拦下。\n\n**优先级理由**\n\nMust：结构判据是这 6 条诉求的主体；只做「可配置」而做不出结构判据，等于没解决。\n\n#### R-3 判据计算可复用\n\n**描述**\n\n同一份 spec 里被多条规则反复用到的计算结果（如「本文有多少条 FR 编号」）应该只算一次并可命名复用，避免每条规则各写一遍、写法还不一致。\n\n**来源与证据**\n\n需求文档 spec 起草时，有 3 条规则都要数 FR 编号；维护者反馈「抄来抄去，改一处漏两处」。\n\n**验收判据**\n\n派生事实后，规则可直接按事实名判断（如 `[requirementCount ≥ 1]`）；派生链后一条能看见前一条。\n\n**优先级理由**\n\nShould：不做也能写出来，只是重复且容易漂移；它降低的是维护成本，不阻断上线。\n\n**依赖与假设**\n\n依赖 R-2 的条件树先可用。\n\n#### R-4 自定义判据逃生舱\n\n**描述**\n\n内置原语覆盖不到时，项目能在 spec 里写一小段判据逻辑（表达式或脚本），并保证它写坏时不会拖垮整次校验。\n\n**来源与证据**\n\n6 条搁置判据里有 2 条不属于任何内置原语：「术语表必须覆盖正文出现的缩写」「日期一律用 YYYY-MM-DD」。\n\n**验收判据**\n\n在 functions 里写 expr/script 后生效；脚本死循环被超时截断并只产出一条失败，其余规则照常执行。\n\n**优先级理由**\n\nShould：只影响少数项目；但它是「不必改插件」这个承诺的最后一块拼图，砍掉就要重新解释哪些判据做不了。\n\n**不做的后果**\n\n那 2 条判据只能继续搁置，维护者会认为「可配置」是半个承诺。\n\n#### R-5 打回时给出目标形状\n\n**描述**\n\n校验失败时，反馈里除了「缺什么」，还要给出目标模板（或按规则反推的骨架）、填写参考的位置、以及剩余可修复次数。\n\n**来源与证据**\n\n3 周 42 份文档中 17 份 PRD 因「缺验收标准」被打回；同一份需求平均要写 2.3 次才过结构校验。评审人访谈：「结构问题占了评审时间的三分之一。」\n\n**验收判据**\n\nblock 文本包含本次新增违规（带行号与建议）、历史违规计数、目标模板或骨架、填写参考路径、剩余次数；agent 下一次 write 即零 error 的比例达 80% 以上。\n\n**优先级理由**\n\nMust：它是 R-1 到「省时间」之间的唯一通道——判据再多，agent 改不对就没有收益。\n\n#### R-6 存量文档豁免\n\n**描述**\n\n只拦本次操作新增的问题，不追溯文件里已有的历史违规；新建文件时按严格口径校验。\n\n**来源与证据**\n\n试点已有 200+ 份存量文档，抽查约三成缺必备章节；若全量追溯，首次启用就会产生上千条违规，维护者会直接关闭校验。\n\n**验收判据**\n\n同一份文档在 before 中已有的违规不计入本次结果；新建（无 before）时等价严格校验。\n\n**优先级理由**\n\nMust：不做则新机制无法在存量项目启用——这是「能不能上线」的门槛，不是体验优化。\n\n#### R-7 机器评审表达质量\n\n**描述**\n\n希望校验能判断「这段话写得好不好、清不清楚」，把评审人从文字问题上也解放出来。\n\n**来源与证据**\n\n2 位评审人提出；但同 3 位评审人也都承认「主要时间消耗在结构问题，不是文字质量」。\n\n**验收判据**\n\n不适用——本期明确不做。主观质量的判据无法机械证伪，误报会直接侵蚀对整套校验的信任。\n\n**优先级理由**\n\nWon't：收益不确定、误报成本高，且会与「只判机器能证伪的结构事实」这条设计纪律冲突。需要时由评审流程解决，不进引擎。\n\n#### R-8 跨文档口径一致性\n\n**描述**\n\n校验同一批文档之间的口径一致性，例如 PRD 里的指标名必须在指标方案里存在、编号必须对得上。\n\n**来源与证据**\n\n上一轮出现 1 次口径分叉：PRD 写「一次修复率」，指标方案叫「修复成功率」，两边对不上。\n\n**验收判据**\n\n待下一期定义——需要跨文件解析、编号对齐与「以哪边为准」的仲裁规则。\n\n**优先级理由**\n\nCould：发生频次低（约 1 次/季度），且实现成本明显高于单文档校验；本期先把单份文档的形状做扎实。\n\n**不做的后果**\n\n偶尔出现两份文档口径不一致，需人工在评审时发现；不影响本期上线。\n\n## 优先级与排序\n\n| 排序方法 | 判据 | 本轮结论 |\n|---|---|---|\n| MoSCoW | Must = 不做则产品不成立；Should = 影响效率或维护成本；Could = 有价值但成本明显更高；Won't = 本期明确不做 | Must：R-1 / R-2 / R-5 / R-6（前两条决定「能不能配置」，后两条决定「能不能落地」）；Should：R-3 / R-4；Could：R-8；Won't：R-7 |\n\n## 需求验证\n\n| 需求编号 | 验证方式 | 结论 | 验证人 |\n|---|---|---|---|\n| R-1 | 3 人访谈交叉核对 + 6 条搁置判据清单复核 | 成立 | 产品组 |\n| R-2 | 用 6 条判据逐条试写条件树，检查是否都能表达 | 成立 | 插件组 |\n| R-3 | 需求文档 spec 起草时实测重复计算次数 | 成立 | 插件组 |\n| R-4 | 用「术语表覆盖缩写」判据做原型验证 | 需修改：需先明确沙箱能力边界 | 插件组 |\n| R-5 | 拿 6 份真实被打回文档做修复演练 | 成立 | 产品组 + 文档组 |\n| R-6 | 对 200+ 份存量文档抽样试跑严格模式，统计历史违规量 | 成立 | 插件组 |\n| R-7 | 评审人访谈 + 判据可机械证伪性走查 | 已证伪：无法机械判定的判据会制造误报 | 产品组 |\n| R-8 | 统计过去一个季度的口径分叉次数 | 成立但低优先：1 次/季度 | 产品组 |\n\n## 变更控制\n\n- **基线**：本文件 v1.0 定于 2026-10-08；基线之后的增删改一律走下表留痕并同步更新「与 PRD 的映射」。\n\n| 日期 | 变更 | 谁提的 | 决策 | 影响 |\n|---|---|---|---|---|\n| 2026-10-08 | 建立基线：R-1～R-8 首次入池 | 产品组 | 接受 | 作为本轮 PRD 的输入 |\n| 2026-10-12 | R-7 由 Could 降为 Won't | 产品组 + 评审人 | 拒绝 | 写入 PRD 非目标；不占用引擎能力 |\n| 2026-10-14 | R-8 由 Should 降为 Could 并延期 | 架构组 | 延期 | 下一期重新评估；本期不做跨文档校验 |\n| 2026-10-14 | R-4 的验收判据补充「脚本写坏不得影响其它规则」 | 插件组 | 接受 | 对应 PRD 的 NFR-2 / NFR-3 |\n\n## 与 PRD 的映射\n\n| 需求编号 | PRD 需求编号 | 状态 |\n|---|---|---|\n| R-1 | FR-1 | 已覆盖 |\n| R-2 | FR-2、FR-4 | 已覆盖 |\n| R-3 | FR-3 | 已覆盖 |\n| R-4 | FR-5 | 已覆盖 |\n| R-5 | FR-6 | 已覆盖 |\n| R-6 | NFR-6 | 已覆盖 |\n| R-7 | 无（见非目标） | 已拒 |\n| R-8 | 无（下一期） | 已延期 |\n\n## 开放问题\n\n| 问题 | 选项 | 负责人 | 截止 |\n|---|---|---|---|\n| R-4 的沙箱能力边界（是否允许读取工作区其它文件） | 只读传入事实 / 允许只读文件 | 插件组 | 2026-10-20 |\n| R-8 是否进入下一期 | 进 / 不进 | 架构组 | 2026-11-15 |\n| 需求池是否需要按项目分文件（当前一个池混装两个试点） | 单池 / 按项目分池 | 产品组 | 已决：单池，用「谁受影响」列区分 |\n\n## 附录\n\n- **原始记录**：访谈纪要 `docs/notes/2026-10-pilot-interviews.md`；返工台账见 PRD 示例的「影响与证据」。\n- **相关文档**：`examples/file-format-specs/prd/example.md`（本轮 PRD）、上一轮需求池 `docs/notes/2026-09-requirements.md`。\n- **变更历史**：2026-10-08 初稿（R-1～R-8 入池）；2026-10-12 拒绝 R-7；2026-10-14 延期 R-8、补充 R-4 验收判据。\n"
  },
  "research": {
    "spec": "# .dsh/file-format-specs/research/spec.yaml —— 调研报告（技术调研 / 竞品分析 / 立项前研究）格式规范\n# 定位：**结论的上游**。PRD 回答「做什么」，设计回答「怎么做」，本文回答\n#   「这个结论凭什么成立」——证据是什么、缺什么、什么条件下结论会翻转。\n# 一份没有证据编号、没有反证、没有信息缺口的「调研报告」，只是把已有观点排版了一遍。\n#\n# 结构取自四条主线的交集：\n#   Google  ：研究文档（Question → Method → Findings → Decision）+ 结论要能被证伪 + Open Questions\n#   Amazon  ：Working Backwards——先写\"要让谁做什么决定\"，再决定去查什么；客户原话优先于二手总结\n#   McKinsey：MECE 问题分解 + 证据分级（来源可查、样本可复现）+ 结论与事实分离\n#   Wiegers ：调研问题也是需求——可验证、可追溯（问题 ↔ 证据双向追溯）+ 干系人验证\n#\n# 两条机器判据（本 spec 比 prd / design 更狠的地方）：\n#   1. 证据分级词表：证据索引表的「来源分级」列只认 A / B / C / D，且必须至少有一条 A 或 B——\n#      只有 D 级（主观判断 / 传闻）的\"调研\"不允许落盘。\n#   2. 问题 ↔ 证据双向追溯：每个 Q-x 的明细必须引用至少一条 E-x；每条 E-x 必须至少被一个 Q-x 引用。\n#      拦住两种最常见的烂尾：问题是拍脑袋来的、证据查完没人用。\next: md\npriority: 78\n# 关键词包含匹配：research 能命中 research.md / 技术调研-xxx.md / 竞品分析.md / 调研报告.md / spike.md\n# 「调研问题」「调研方法」故意不在这里声明——它们是章节名，单看文件名像报告正文，容易抢单。\nmatch:\n  - \"research\"\n  - \"调研报告\"\n  - \"技术调研\"\n  - \"竞品分析\"\n  - \"选型报告\"\n  - \"spike\"\nmode: block\ndiff_mode: delta\nmax_attempts: 3\non_exhausted: allow\n\n# —— 规则引擎 ——\nderive:\n  # 编号条数必须数「清单表的行」——不能数全文里 Q-x / E-x 的出现次数（同一条会被引用多次，\n  # 而且 E-2 可能只出现在正文引用里）。script / expr 派生拿到的是文档级变量：doc / text / api，\n  # 没有 tables 事实，所以从 doc.tables 里自己找。\n  # 注：facts 在多个 spec 之间共享，这里的 fact 名带 research 前缀以免串台。\n  - fact: researchQuestionList\n    script: |\n      const t = doc.tables.find((x) => x.header.join('|').includes('调研问题'))\n      if (!t) return { count: 0, ids: [] }\n      const i = t.header.findIndex((c) => c.includes('编号'))\n      const ids = i < 0 ? [] : t.rows.map((r) => String(r[i] ?? '').trim()).filter((v) => /^Q-\\d+$/.test(v))\n      return { count: ids.length, ids: ids }\n  - fact: researchQuestionCount\n    expr: \"(researchQuestionList && researchQuestionList.count) || 0\"\n  - fact: researchEvidenceIndex\n    script: |\n      const t = doc.tables.find((x) => x.header.join('|').includes('来源分级'))\n      if (!t) return { count: 0, ids: [] }\n      const i = t.header.findIndex((c) => c.includes('编号'))\n      const ids = i < 0 ? [] : t.rows.map((r) => String(r[i] ?? '').trim()).filter((v) => /^E-\\d+$/.test(v))\n      return { count: ids.length, ids: ids }\n  - fact: researchEvidenceCount\n    expr: \"(researchEvidenceIndex && researchEvidenceIndex.count) || 0\"\n  - fact: researchEvidenceIds\n    expr: \"(researchEvidenceIndex && researchEvidenceIndex.ids) || []\"\n\nfunctions:\n  hasOwner:\n    expr: \"!!(frontmatter.owner || frontmatter.owner_team)\"\n\n  noPlaceholder:\n    expr: \"!/TODO|TBD|待补充/.test(text)\"\n\n  # 判据 1a：结论表的「立场」列必须是固定词表。\n  # 「建议采纳 / 再想想 / 看情况」这类写法无法被下游引用，也无法机械判断结论是否已经给出——\n  # 出现即打回。与 requirement 的 MoSCoW 词表同一手法。\n  #\n  # 注：脚本上下文只注入 doc / text / api（白名单），**看不到同一个 spec 里的其他函数**，\n  # 所以每个脚本自带一个三行的 findTable 小工具，不跨函数复用。\n  decisionVocabulary:\n    script: |\n      const findTable = (need, cols) => {\n        const t = doc.tables.find((x) => need.every((k) => x.header.join('|').includes(k)))\n        if (!t) return null\n        return { t, i: t.header.findIndex((c) => cols.some((k) => c.includes(k))) }\n      }\n      const found = findTable(['决策', '结论'], ['立场'])\n      if (!found) return []\n      const { t, i } = found\n      if (i < 0) return []\n      const ok = ['采纳', '不采纳', '有条件采纳', '继续调研']\n      return t.rows.flatMap((row, n) => {\n        const v = String(row[i] ?? '').trim()\n        if (v === '' || ok.includes(v)) return []\n        return [{\n          message: '结论表第 ' + (n + 1) + ' 行立场「' + v + '」不在词表（采纳 / 不采纳 / 有条件采纳 / 继续调研）',\n          line: t.line,\n          key: 'stance:' + n,\n        }]\n      })\n\n  # 判据 1b：证据分级 + 至少一条高等级证据。\n  # A 官方文档或源码 / B 可复现实测 / C 二手资料 / D 主观判断；只有 D 级不算调研。\n  evidenceClass:\n    script: |\n      const findTable = (need, cols) => {\n        const t = doc.tables.find((x) => need.every((k) => x.header.join('|').includes(k)))\n        if (!t) return null\n        return { t, i: t.header.findIndex((c) => cols.some((k) => c.includes(k))) }\n      }\n      const found = findTable(['证据', '来源分级'], ['来源分级'])\n      if (!found) return []\n      const { t, i } = found\n      if (i < 0) return []\n      const ok = ['A', 'B', 'C', 'D']\n      const out = []\n      let strong = 0\n      t.rows.forEach((row, n) => {\n        const v = String(row[i] ?? '').trim().toUpperCase()\n        if (v === 'A' || v === 'B') strong += 1\n        if (v === '') {\n          out.push({ message: '证据索引第 ' + (n + 1) + ' 行缺来源分级（A / B / C / D）', line: t.line, key: 'class-missing:' + n })\n          return\n        }\n        if (!ok.includes(v)) {\n          out.push({ message: '证据索引第 ' + (n + 1) + ' 行来源分级「' + v + '」不在词表（A 官方 / B 实测 / C 二手 / D 主观）', line: t.line, key: 'class:' + n })\n        }\n      })\n      if (t.rows.length > 0 && strong === 0) {\n        out.push({ message: '证据索引里至少要有 1 条 A 级（官方文档 / 源码）或 B 级（可复现实测）证据：只有 C / D 级不能支撑结论', line: t.line, key: 'class-strong' })\n      }\n      return out\n\n  # 判据 2：问题 ↔ 证据双向追溯（本 spec 的核心）。\n  #   问题 → 证据：每个 Q-x 的明细小节里必须引用至少一个 E-x，否则这个 Q 是拍脑袋来的。\n  #   证据 → 问题：每条 E-x 必须被至少一个 Q-x 引用，否则这条证据查完没人用（或者该补一个调研问题）。\n  questionEvidenceTrace:\n    script: |\n      const toIds = (list) => (Array.isArray(list) ? list : []).map(String)\n      // 清单行来自 derive（researchQuestionList / researchEvidenceIndex）：只认表里的编号，\n      // 不把正文里的引用当成一条问题 / 一条证据。\n      const qIds = toIds(researchQuestionList && researchQuestionList.ids)\n      const eIds = toIds(researchEvidenceIndex && researchEvidenceIndex.ids)\n      if (qIds.length === 0 || eIds.length === 0) return []\n\n      // 要的是「每个 Q-x 的小节里引用了哪些 E-x」，不是全文引用：所以需要行的下标。\n      const idxOf = new Map()\n      doc.bodyLineNos.forEach((n, i) => idxOf.set(n, i))\n      const blockOf = (id) => {\n        const h = doc.headings.find((x) => new RegExp('^' + id + '\\\\b').test(x.text.trim()))\n        if (!h) return ''\n        const start = idxOf.get(h.line)\n        if (start === undefined) return ''\n        let end = doc.bodyLines.length\n        for (const o of doc.headings) {\n          if (o.line <= h.line || o.level > h.level) continue\n          const j = idxOf.get(o.line)\n          if (j !== undefined && j < end) end = j\n        }\n        return doc.bodyLines.slice(start, end).join('\\n')\n      }\n\n      const refsOf = new Map()\n      const out = []\n      for (const id of qIds) {\n        const refs = api.collectIds(blockOf(id), ['E'])\n        refsOf.set(id, refs)\n        if (refs.length === 0) {\n          out.push({ message: id + ' 的明细没有引用任何证据编号（E-x）：调研问题必须落到证据上', key: 'q-no-evidence:' + id })\n        }\n      }\n      for (const id of eIds) {\n        const used = qIds.some((k) => (refsOf.get(k) || []).indexOf(id) >= 0)\n        if (!used) {\n          out.push({ message: id + ' 没有被任何调研问题引用：要么补上它服务的 Q-x，要么从证据索引里删掉', key: 'e-unused:' + id })\n        }\n      }\n      return out\n\nrules:\n  - id: fm\n    assert:\n      fn: frontmatterRequired\n      args:\n        - keys: [title, status]\n  - id: status-enum\n    assert: { fn: frontmatterEnum, args: [{ key: status, values: [draft, review, approved, superseded] }] }\n\n  # 必备章节，按调研推进顺序（结构节只认 H2）\n  - id: sections\n    assert:\n      fn: sectionsRequired\n      args:\n        - order: true\n          headings:\n            - 摘要\n            - 背景与调研问题\n            - 调研方法与范围界定\n            - 决策与结论\n            - 证据索引\n            - 关键发现\n            - 方案对比矩阵\n            - 结论与建议\n            - 风险与不确定性\n            - 开放问题\n            - 附录\n\n  # 关键表格：缺表 / 缺列 / 行数不足都会被打回\n  # 调研问题清单：问题 + 为什么值得查（决策影响）+ 影响程度\n  - id: question-table\n    assert: { fn: tableRequired, args: [{ under: 背景与调研问题, header: [编号, 调研问题, 决策影响, 影响程度] }] }\n  # 每个 Q-x 都要有明细：调研问题 / 决策影响 / 调研与证据 必填，且「调研与证据」里必须有 E-x\n  # （反证与限定条件按需：写了就不能空）\n  - id: question-details\n    assert: { fn: idDetails, args: [{ under: 背景与调研问题, fields: [调研问题, 决策影响, 调研与证据], optional: [反证与限定条件] }] }\n  # Amazon Working Backwards：先写清\"要让谁做什么决定\"，再决定去查什么\n  - id: decision-table\n    assert: { fn: tableRequired, args: [{ under: 决策与结论, header: [决策编号, 要做的决定, 决策人, 截止], min_rows: 1 }] }\n  # 证据索引：来源分级这一列是本 spec 的判据 1\n  - id: evidence-table\n    assert: { fn: tableRequired, args: [{ under: 证据索引, header: [编号, 证据, 来源分级, 获取方式与日期] }] }\n  # 关键发现：每条发现都要能指回证据；fact / inference 分列，结论与事实不许混写\n  - id: finding-table\n    assert: { fn: tableRequired, args: [{ under: 关键发现, header: [编号, 发现, 支撑证据, 事实或推断, 可信度] }] }\n  # 对比矩阵：维度必须在同一口径下逐项打分——没有矩阵的对比就是各说各话\n  - id: matrix-table\n    assert: { fn: tableRequired, args: [{ under: 方案对比矩阵, header: [评估维度, 权重] , min_rows: 4 }] }\n  # 结论：立场词表由 decisionVocabulary 判，这里管结构\n  - id: conclusion-table\n    assert: { fn: tableRequired, args: [{ under: 结论与建议, header: [决策编号, 结论, 立场, 成立条件, 翻转条件] }] }\n  # 不确定性：没写出来的盲区不会自己消失；结论失效的触发条件必须显式\n  - id: uncertainty-table\n    assert: { fn: tableRequired, args: [{ under: 风险与不确定性, header: [信息缺口, 影响哪个结论, 获取成本, 处理方式] }] }\n  - id: open-questions\n    assert: { fn: tableRequired, args: [{ under: 开放问题, header: [问题, 选项, 负责人, 截止] }] }\n\n  - id: has-owner\n    when: { path: \"frontmatter.status\", op: \"notEmpty\" }   # 守卫：只对有 status 的文档生效\n    assert: { fn: \"hasOwner\", message: \"调研报告必须有 owner 或 owner_team\" }\n    priority: 10\n\n  - id: at-least-one-question\n    assert: { path: \"researchQuestionCount\", op: \"gte\", value: 1, message: \"调研问题清单至少一条编号（Q-1…）：没有问题清单的调研没有边界\" }\n  - id: at-least-two-evidence\n    assert: { path: \"researchEvidenceCount\", op: \"gte\", value: 2, message: \"证据索引至少两条编号（E-1 / E-2…）：单一来源不能支撑调研结论\" }\n\n  # 两条核心判据（动态函数）\n  - id: evidence-class\n    assert: { fn: evidenceClass }\n  - id: question-evidence-trace\n    assert: { fn: questionEvidenceTrace }\n  - id: decision-vocabulary\n    assert: { fn: decisionVocabulary }\n\n  - id: no-placeholder\n    severity: warning\n    assert: { fn: noPlaceholder, message: \"文档里不能留 TODO / TBD / 待补充\" }\n",
    "template": "---\ntitle: <调研主题> 调研报告\nstatus: draft\nowner: <调研负责人 / DRI>\nreviewers: <评审人>\ndecision: <本调研服务的决策 / 相关 PRD 路径>\ncreated: <YYYY-MM-DD>\nupdated: <YYYY-MM-DD>\n---\n\n# <调研主题> 调研报告\n\n（说明：本报告回答「这个结论凭什么成立」。每个 `##` 标题都要带 `serves:` 标注：指向它服务的调研问题（`Q-x`）或决策编号（`D-x`），全文性章节写「全文」。**必须**：每个 `Q-x` 的明细里要有 `E-x` 证据编号；每条 `E-x` 都要被至少一个 `Q-x` 引用；证据索引至少一条 `A` 级或 `B` 级。**禁止**：只写结论不写证据、只写二手总结不给原文出处、把推断写成事实。）\n\n## 摘要  serves: 全文\n\n（说明：5 行以内回答四问——调研问题是什么 / 用了什么办法 / 结论是什么 / 证据强度如何。细节留给后面各节，这里只给读者一张地图。）\n\n- **调研问题**：<一句话说清要回答什么>\n- **办法**：<看了什么、测了什么、问了多少人；覆盖范围与时间窗>\n- **结论**：<Q-1 的答案 + D-1 的建议，写立场词（采纳 / 不采纳 / 有条件采纳 / 继续调研）>\n- **证据强度**：<A 级几条、B 级几条；最大的信息缺口是什么>\n- **这份调研不能用来决定什么**：<边界，防止结论被外推滥用>\n\n## 背景与调研问题  serves: 全文\n\n（说明：Amazon 的 Working Backwards——先写清「要让谁、在什么时候、做什么决定」，再决定去查什么。查不出决策影响的问题不要写进清单。）\n\n### 要不要查：决策背景\n\n（说明：讲清触发这次调研的事件、现在的做法与代价、以及「不查直接拍」的风险。用事实与原话，不写「大家都很关心」。）\n\n### 调研问题清单\n\n（说明：问题要可回答——「哪个更好」不是问题，「在 X 约束下哪个方案能撑住 Y 量级」才是。影响程度只认 高 / 中 / 低。）\n\n| 编号 | 调研问题 | 决策影响 | 影响程度 |\n|---|---|---|---|\n| Q-1 | <可回答的问题> | <这条答案会让哪个决策怎么变> | <高 / 中 / 低> |\n| Q-2 | <可回答的问题> | <同上> | <高 / 中 / 低> |\n\n### 调研问题明细\n\n#### Q-1 <问题短名>\n\n**调研问题**\n\n<把问题写成可以被证据推翻的一句话：限定条件、量级、时间窗都要在句子里。>\n\n**决策影响**\n\n<哪个决策编号（D-x）会因为这条答案改变；答「是」和答「否」分别会怎么做。>\n\n**调研与证据**\n\nE-1（<证据一句话>）、E-2（<证据一句话>）。写清这几条证据合起来为什么足以回答本问题。\n\n**反证与限定条件**（有反例或例外才写；没有就删掉这一块）\n\n- <什么证据会推翻上面的回答；结论成立需要哪些前提>\n\n#### Q-2 <问题短名>\n\n**调研问题**\n\n<限定条件 + 量级 + 时间窗。>\n\n**决策影响**\n\n<本问题服务哪个 D-x。>\n\n**调研与证据**\n\nE-1（<证据一句话>）、E-3（<证据一句话>）、E-4（<证据一句话>）。\n\n**反证与限定条件**（有才写；没有就删掉这一块）\n\n- <反例 / 前提>\n\n## 调研方法与范围界定  serves: 全文\n\n（说明：McKinsey 的口径——方法、样本、时间窗写在前面，读者才能判断结论能外推到哪。范围界定要把「明确不查」的写出来，否则会被追问「为什么不查 X」。）\n\n| 方法 | 具体做法 | 样本与规模 | 时间窗 | 局限 |\n|---|---|---|---|---|\n| <文档与源码研读 / 原型实测 / 深度访谈 / 问卷 / 竞品试用> | <怎么做的，可复现到别人能照做> | <n = ?> | <YYYY-MM-DD ~ YYYY-MM-DD> | <覆盖不到谁 / 环境差异> |\n\n**范围界定**\n\n- **纳入**：<哪些方案 / 场景 / 版本在范围内>\n- **排除**：<哪些明确不查，以及为什么（成本 / 不相关 / 已有结论）>\n- **不做的事**：<本报告不做的判断，例如「不做成本估算」「不评价组织可行性」>\n\n## 决策与结论  serves: 全文\n\n（说明：先摆决策与建议，再摆证据——决策人只看这一节也能做决定，细节在后面各节。决策编号 D-x 是全文的锚点：调研问题、结论、开放问题都要指回它。）\n\n| 决策编号 | 要做的决定 | 决策人 | 截止 |\n|---|---|---|---|\n| D-1 | <要在什么时间前决定什么> | <谁拍板> | <YYYY-MM-DD / 已决> |\n\n**当前建议**（一屏以内讲完：建议怎么选、依据哪几条证据、什么条件下这个建议会变）\n\n<...>\n\n## 证据索引  serves: 全文\n\n（说明：**来源分级是本 spec 的判据**——A 官方文档或源码 / B 可复现实测（含命令与结果）/ C 二手资料（文章、博客、他人转述）/ D 主观判断与经验。整份报告至少要有 1 条 A 或 B；`获取方式与日期` 要写到别人能自己复查。每条 E-x 都必须被某个 Q-x 引用，查完没人用的证据应该删掉。）\n\n| 编号 | 证据 | 来源分级 | 获取方式与日期 |\n|---|---|---|---|\n| E-1 | <证据一句话：出处 + 关键内容，不写\"文档里说了\"> | A | <URL / 仓库路径 + commit、命令 + 结果、访谈对象与形式>（YYYY-MM-DD） |\n| E-2 | <实测> | B | <可复现步骤：环境 / 命令 / 观测点>（YYYY-MM-DD） |\n| E-3 | <二手资料> | C | <文章标题与链接>（YYYY-MM-DD） |\n| E-4 | <判断与经验> | D | <来源：谁的经验 / 哪个项目的教训>（YYYY-MM-DD） |\n\n## 关键发现  serves: <Q-1>\n\n（说明：**事实与推断分列**——「支持 X」是事实，「所以我们应该上 X」是推断，两者混写是调研失效的主要原因。可信度只认 高 / 中 / 低。每条发现都要能顺着编号指回去。）\n\n| 编号 | 发现 | 支撑证据 | 事实或推断 | 可信度 |\n|---|---|---|---|---|\n| F-1 | <一句话，可证伪> | E-1 | 事实 | 高 |\n| F-2 | <一句话> | E-2、E-3 | 推断 | 中 |\n\n### 与直觉相反的地方\n\n（说明：和团队现有认知不一样、或者推翻了最初假设的发现。没有就写「截至本次调研没有——最危险假设是 X，见风险与不确定性」。）\n\n## 方案对比矩阵  serves: <Q-2>\n\n（说明：维度必须在同一口径下逐项打分——没有矩阵的对比就是各说各话。权重合计 100%；`标注` 写清打分依据的证据编号，缺依据的格子写「无证据」，不要**留空**。）\n\n| 评估维度 | 权重 | <候选 A> | <候选 B> | <维持现状> | 标注 |\n|---|---|---|---|---|---|\n| 功能覆盖 | 30% | <3 / 5> | <4 / 5> | <2 / 5> | E-1 |\n| 性能与容量 | 25% | <…> | <…> | <…> | E-2 |\n| 集成与迁移成本 | 20% | <…> | <…> | <…> | E-3 |\n| 生态与维护活跃度 | 15% | <…> | <…> | <…> | E-1 |\n| 合规与安全 | 10% | <…> | <…> | <…> | E-4 |\n\n## 结论与建议  serves: 全文\n\n（说明：**立场列是机器判据**，只认 采纳 / 不采纳 / 有条件采纳 / 继续调研——下游文档、评审、以及三个月后的你自己都要能直接引用它。「成立条件」和「翻转条件」是硬要求：写不出翻转条件的结论不是结论，是偏好。）\n\n| 决策编号 | 结论 | 立场 | 成立条件 | 翻转条件 |\n|---|---|---|---|---|\n| D-1 | <一句话结论，含选型结果> | 采纳 | <哪些前提成立时这条结论有效> | <看到什么证据就该推翻它> |\n\n**不采纳的方案与理由**（本调研明确否掉的选项，防止半年后重新讨论一遍）\n\n- <方案 / 做法>：<否掉的依据（E-x）>\n\n## 风险与不确定性  serves: 全文\n\n（说明：没写出来的盲区不会自己消失。信息缺口要落到「影响哪个结论、要花多少成本才能补上、这次补不补」——补不了的，写清结论在什么情况下失效。）\n\n**最危险假设**（如果它错了，上面哪条结论直接作废）\n\n- <假设>：<错了会怎样；用什么最便宜的方式证伪>\n\n| 信息缺口 | 影响哪个结论 | 获取成本 | 处理方式 |\n|---|---|---|---|\n| <没查到 / 查不了的事> | <Q-x / D-x> | <人日 / 环境要求> | <本次补 / 下次补 / 接受不确定性并写明失效条件> |\n\n## 开放问题  serves: 全文\n\n（说明：每个问题给选项、负责人和截止。截止到了没有结论，就写「已决 + 结论」。）\n\n| 问题 | 选项 | 负责人 | 截止 |\n|---|---|---|---|\n| <待定问题> | <备选项> | <谁> | <日期 / 已决> |\n\n## 附录  serves: 全文\n\n（说明：原始材料放这里——访谈记录、问卷、benchmark 脚本、截图、相关文档。评审结论与后续变更也在这里留痕。）\n\n- **访谈与问卷**：<对象、形式、记录位置>\n- **实测脚本与原始数据**：<脚本路径、数据位置；E-2 的复现命令>\n- **相关文档**：<PRD / 设计文档 / 上游调研>\n- **评审与复议记录**：<日期、参与人、结论（评审意见定级后冻结为基线）>\n- **变更历史**：<何时改了什么；结论翻转必须写清触发证据>\n",
    "example": "---\ntitle: 内容格式校验子系统 调研报告\nstatus: approved\nowner: 插件组\nreviewers: 架构组、宿主组\ndecision: 是否给 dsh-file-enhance 增加内容格式校验子系统（对应 D-1 / D-2 / D-3）\ncreated: 2026-10-13\nupdated: 2026-10-15\n---\n\n# 内容格式校验子系统 调研报告\n\n## 摘要  serves: 全文\n\n- **调研问题**：给 dsh-file-enhance 增加「文档内容格式校验」子系统，是值得做、还是应该把它交给 prompt 纪律与人工评审？\n- **办法**：研读宿主与插件源码（E-1）、在临时工作区跑通 4 组判据探针（E-2）、比对 Google / Amazon 的公开研究文档规范（E-3）、访谈 3 个项目组与 2 名评审人（E-4、E-5）。\n- **结论**：**采纳**——判据数据化 + 落盘后校验的收益已被两个真实工作区验证（E-2、E-5）；但**不采纳**把校验做成「写入前阻塞」（E-6），并且必须接受「文件已落盘后才打回」这一取舍（见风险与不确定性）。\n- **证据强度**：A 级 2 条、B 级 2 条、C 级 2 条、D 级 1 条；最大缺口是「跨团队规模效应」只有 2 个样本，见风险与不确定性。\n- **这份调研不能用来决定什么**：不评价 UI / 交互形态，不做成本与排期估算，不覆盖非 markdown 文件类型。\n\n## 背景与调研问题  serves: 全文\n\n### 要不要查：决策背景\n\n现有插件的路径子系统（`.dsh/folder-path-rules/`）已经解决了「文件放哪、叫什么」，但内容层面的问题原样留着：需求文档缺章节、PRD 的 FR 编号与明细对不上、指标没有埋点可追。今天的替代做法是在 prompt 里写一段「请遵循以下文档结构」，代价是三条：判据进不了版本控制（E-5）、模型每次都可能漏（E-4）、出了问题没有人能说清「哪条判据没过」。\n\n要不要动，取决于一个具体判断：**内容判据能不能被机器判，以及判错的代价是否可接受**。前者决定有没有用，后者决定会不会变成每日噪音——所以这次调研只查这两件事，不查「要不要做可视化」这类产品形态问题。\n\n### 调研问题清单\n\n| 编号 | 调研问题 | 决策影响 | 影响程度 |\n|---|---|---|---|\n| Q-1 | 文档结构类判据（必备章节 / 表格列 / 编号连续性）能否在不引入自然语言理解的前提下机械判定？ | D-1：答否 → 整个子系统不立项 | 高 |\n| Q-2 | 「落盘后校验并允许重试」与「写入前阻塞」两种接入方式，哪一种的总代价更低？ | D-2：决定接在 post-execute 还是 pre-execute | 高 |\n| Q-3 | 判据数据化（放工作区 YAML）比内置在插件代码里，一次改判据的端到端成本差多少？ | D-3：决定 spec 是否放工作区、是否热重载 | 中 |\n| Q-4 | 校验判据的误报会以什么形式、多大频率影响日常写作？ | D-1 / D-2：决定默认 severity 与 delta 归责策略 | 中 |\n\n### 调研问题明细\n\n#### Q-1 结构类判据能否机械判定\n\n**调研问题**\n\n在不使用大模型判定、只依赖文本结构解析的前提下，能否对「必备 H2 章节」「表格必备列」「编号连续与唯一」「frontmatter 字段」四类判据给出可复现的判定结果？\n\n**决策影响**\n\nD-1。答「能」则立项；答「不能」或「误判率高」则整条产品线不成立，退回到 prompt 纪律 + 人工评审的组合。\n\n**调研与证据**\n\nE-1（宿主 `PreToolDecision` / `PostToolDecision` 契约与 `write` 的 after 全文来源）、E-2（4 组探针：缺章节 / 缺列 / 编号跳号 / 值域越界全部被捕获，且代码围栏内的假结构未误伤）。\n\n**反证与限定条件**\n\n- 反证：语义类判据（「验收标准是否可验证」）无法机械判定——本结论只覆盖结构类，见风险与不确定性。\n- 前提：文档解析必须先剥离代码围栏，否则 `## 假标题` 会造成系统性误判（E-2 第 2 组探针就是这条）。\n\n#### Q-2 落盘后校验与写入前阻塞的代价对比\n\n**调研问题**\n\n在宿主现有工具契约下，两种接入方式各需要多少改动、对 agent 的往返次数与最终文件状态分别有什么影响？\n\n**决策影响**\n\nD-2。决定校验挂在 `tools/post-execute`（落盘后）还是 `tools/pre-execute`（落盘前），也决定 agent 是按「一次写对」还是「写错再改」工作。\n\n**调研与证据**\n\nE-1（`pre-execute` 只能 allow / deny / cancel / ask，且 `exec.arguments` 深度冻结，插件无法改写 `file_path`）、E-3（Google 研究文档规范与 Amazon 的 FAQ 结构都以「先写出草稿再按清单收敛」为工作方式）、E-6（工程判断：内容判据需要看到全文才能判，而 `pre-execute` 阶段拿不到 after 全文）。\n\n**反证与限定条件**\n\n- 反证：若宿主将来允许插件改写工具入参，「写入前纠正」的成本会降到与落盘后接近，本结论需要复议（E-1 的接口契约是唯一依据）。\n- 代价必须显式接受：落盘后打回意味着**不合规的文件已经写在磁盘上**，重试期间其他人可能读到半成品。\n\n#### Q-3 判据数据化与内置代码的成本差\n\n**调研问题**\n\n一次「项目想加一条自己的判据」的操作，从规则住工作区 YAML（热重载）与规则住插件源码（构建 + 重装 + 重启）两种形态看，端到端耗时与回归风险分别是多少？\n\n**决策影响**\n\nD-3。决定 spec 是否放 `.dsh/file-format-specs/`、是否需要 mtime 热重载、是否需要 `file_propose` 这类自助入口。\n\n**调研与证据**\n\nE-4（某团队把 6 条文档结构要求写进 prompt，两周内 3 次因模型漏读在第 12 节之后开始出现缺章节）、E-5（访谈记录：判据进 prompt 后无法 review、无法回归）。\n\n**反证与限定条件**\n\n- 前提：YAML 规则的表达力足够覆盖项目判据；表达力不足时必须留逃生舱（`expr` / `script`），否则团队会退回改代码。\n\n#### Q-4 误报的形态与频率\n\n**调研问题**\n\n在真实写作节奏下，结构类判据打回里有多少是「真错」、多少是「作者有意为之」，分别出现在什么阶段？\n\n**决策影响**\n\nD-1 / D-2。决定默认 `diff_mode`（delta 还是 strict）、`max_attempts`、`on_exhausted`，以及是否保留 warning 级别。\n\n**调研与证据**\n\nE-4（3 个项目组的补写记录与评审意见：多数缺失出现在文档后半段，属于写到最后赶工）、E-5（评审人指出的历史遗留文档问题不应由本次编辑背锅，这条直接支持 delta 归责）。\n\n**反证与限定条件**\n\n- 限定：只有 2 个团队的样本，规模效应未验证；跨团队结论按低可信度处理。\n- 反证：若作者频繁「有意偏离」判据，说明判据本身过严，应改 spec 而不是放宽校验。\n\n## 调研方法与范围界定  serves: 全文\n\n| 方法 | 具体做法 | 样本与规模 | 时间窗 | 局限 |\n|---|---|---|---|---|\n| 文档与源码研读 | 逐个读宿主工具契约、`write`/`edit` 结果结构、插件的判定链实现，记为 E-1 | 宿主 1 份 + 插件 2 个子系统 | 2026-10-13 ~ 2026-10-14 | 只覆盖当前版本，接口变更后需复议 |\n| 原型实测 | 在临时工作区构造 4 组文档，跑判据探针并记录通过 / 打回结果与行号 | 4 组 × 每类 2 个变体 | 2026-10-14 | 探针由作者构造，可能偏向已知判据 |\n| 规范比对 | 比对 Google、Amazon 的公开文档结构要求，看章节集合是否有共识 | 3 份公开规范 | 2026-10-14 | 均为大厂场景，团队规模差异未控制 |\n| 访谈 | 半结构化访谈 3 个项目组 + 2 名评审人，逐条记录原文 | n = 5 | 2026-10-14 ~ 2026-10-15 | 样本量小，无问卷量化 |\n| 竞品试用 | 试用 2 个文档 lint 工具，观察其对语义类判据的处理 | 2 个工具 | 2026-10-15 | 只做定性比较 |\n\n**范围界定**\n\n- **纳入**：markdown 文档的结构类判据、`write` / `edit` 两个入口、单工作区内的规则分发。\n- **排除**：自然语言语义判据、非 markdown 文件、跨仓库规则共享——成本高且与本决策无关。\n- **不做的事**：不做成本与排期估算，不评价 UI，不给出「组织是否愿意维护判据」的判断。\n\n## 决策与结论  serves: 全文\n\n| 决策编号 | 要做的决定 | 决策人 | 截止 |\n|---|---|---|---|\n| D-1 | 是否立项内容格式校验子系统 | 插件组负责人 | 2026-10-16 |\n| D-2 | 校验接在 post-execute 还是 pre-execute，以及默认归责策略 | 插件组负责人 + 宿主组 | 2026-10-16 |\n| D-3 | spec 是否放工作区并支持热重载 | 插件组 | 已决 |\n\n**当前建议**\n\n立项（D-1 采纳），校验接 `tools/post-execute` 并默认 `diff_mode: delta`（D-2 采纳），spec 放工作区 `.dsh/file-format-specs/` 并按 mtime 热重载（D-3，已落地）。依据是 E-1 的接口契约与 E-2 的探针结果；如果 E-1 的契约在宿主侧变更（允许改写工具入参），D-2 需要复议。\n\n## 证据索引  serves: 全文\n\n| 编号 | 证据 | 来源分级 | 获取方式与日期 |\n|---|---|---|---|\n| E-1 | 宿主 `pre-execute` 只有 allow / deny / cancel / ask 四档决策，且 `exec.arguments` 被深度冻结；`write` / `edit` 的 post 结果里带最终全文 `after` | A | 读宿主与插件源码：`@deepseek-ai/dsh-tools` 决策类型定义、`tools/src/index.ts` 的 arguments 冻结处（2026-10-13） |\n| E-2 | 4 组结构判据探针全部被捕获：缺章节、缺表格列、编号跳号、frontmatter 值域越界；代码围栏内的假标题与假表格未触发误报 | B | 临时工作区构造文档并跑 `validateDocument`，脚本与输入见附录（2026-10-14） |\n| E-3 | Google 设计文档与 Amazon PR-FAQ 都要求固定的章节集合与「先草稿后按清单收敛」的工作方式 | A | 官方公开文档（industrialempathy.com/posts/design-docs-at-google、aboutamazon.com/news/workplace/working-backwards）（2026-10-14） |\n| E-4 | 某团队把 6 条文档结构要求写进 prompt，两周内 3 次缺章节，全部出现在文档第 12 节之后；同时该团队的评审补写记录显示缺失集中在收尾阶段 | C | 该项目组的补写记录与评审意见摘录（2026-10-14） |\n| E-5 | 访谈 3 个项目组 + 2 名评审人：判据写进 prompt 后无法 review、无法回归；评审人明确反对把历史遗留问题算到本次编辑头上 | C | 半结构化访谈，逐条原文记录（2026-10-15） |\n| E-6 | 工程判断：内容判据需要 document 全文，`pre-execute` 阶段拿不到 after 全文，因此「写入前纠正」在现有契约下不可行 | D | 插件组内部评审意见（2026-10-15） |\n\n## 关键发现  serves: Q-1\n\n| 编号 | 发现 | 支撑证据 | 事实或推断 | 可信度 |\n|---|---|---|---|---|\n| F-1 | 四类结构判据（章节 / 表格列 / 编号 / frontmatter）可机械判定，且解析器剥离代码围栏后无系统性误报 | E-2 | 事实 | 高 |\n| F-2 | 宿主 `pre-execute` 只提供四档决策且入参冻结，插件无法在写入前改写路径或内容 | E-1 | 事实 | 高 |\n| F-3 | 结构判据写在 prompt 里会随文档长度衰减，缺失集中在长文档后段 | E-4 | 推断 | 中 |\n| F-4 | 历史遗留文档的旧违规必须与本次编辑分离，否则校验会被当成噪音关掉 | E-5 | 推断 | 中 |\n| F-5 | 「写入前纠正」在现有契约下不可行，落盘后打回是当前唯一可行接入点 | E-1、E-6 | 推断 | 中 |\n\n### 与直觉相反的地方\n\n最初假设是「阻塞式校验（写入前拦下）体验更好」，调研推翻了它：`pre-execute` 阶段既拿不到全文、也无法改写入参（E-1），阻塞式只能退化成「写一次、拒一次、再写一次」的两倍往返；反而是落盘后打回 + 目标模板注入能让 agent 一次改对（F-5）。\n\n## 方案对比矩阵  serves: Q-2\n\n| 评估维度 | 权重 | 判据数据化 + 落盘后校验 | 判据内置 + 写入前阻塞 | 维持现状（prompt 纪律） | 标注 |\n|---|---|---|---|---|---|\n| 判据可表达性 | 30% | 4 / 5（结构类全覆盖，语义类需脚本逃生舱） | 4 / 5（同等表达力） | 1 / 5（不可机械判定） | E-1、E-2 |\n| 一次改对的往返次数 | 25% | 4 / 5（打回时附目标模板） | 2 / 5（拿不到全文，需两次往返） | 2 / 5（靠模型自觉，长文衰减） | E-1、E-3 |\n| 判据可维护性 | 20% | 5 / 5（工作区 YAML，改文件即生效） | 2 / 5（改代码 + 构建 + 重装） | 1 / 5（进不了版本控制） | E-5 |\n| 评审与回归友好度 | 15% | 5 / 5（判据可 review、可 delta 归责） | 5 / 5 | 1 / 5 | E-5 |\n| 落地成本与风险 | 10% | 3 / 5（新增子系统，但只读 post 钩子） | 2 / 5（需要宿主改契约，跨团队协作） | 5 / 5（零成本，问题原样保留） | E-6 |\n\n## 结论与建议  serves: 全文\n\n| 决策编号 | 结论 | 立场 | 成立条件 | 翻转条件 |\n|---|---|---|---|---|\n| D-1 | 立项内容格式校验子系统：判据数据化 + 落盘后校验 | 采纳 | 结构类判据足够覆盖团队诉求；宿主保留 post-execute 钩子与 after 全文 | 出现「结构判据无法覆盖、语义判据才是主要痛点」的实测证据 |\n| D-2 | 校验接 `tools/post-execute`，默认 `diff_mode: delta`，`max_attempts: 3`，用尽后放行 | 采纳 | `pre-execute` 仍然不可改写入参、不可读全文 | 宿主开放入参改写，或 delta 归责被证明会漏掉真实违规 |\n| D-3 | spec 放工作区 `.dsh/file-format-specs/`，按 mtime 热重载 | 采纳 | 规则作者就是项目成员，愿意用 YAML 表达判据 | 判据复杂度超出 YAML + 脚本表达力，团队退回改代码 |\n\n**不采纳的方案与理由**\n\n- **写入前阻塞式校验**：`pre-execute` 阶段拿不到全文、无法改写入参，只能退化成两次往返（E-1、E-6）。\n- **把判据继续留在 prompt 里**：长文档后段系统性缺失，且判据无法 review 与回归（E-4、E-5）。\n- **内置一套「默认判据」随插件分发**：判据的权威必须属于项目自己，否则项目会用「改判据」代替「改文档」（E-5）。\n\n## 风险与不确定性  serves: 全文\n\n**最危险假设**\n\n- 假设「结构类判据就是团队的主要痛点」。如果实际痛点在语义（例如「验收标准是否可验证」），本子系统的收益会大幅缩水——最便宜的证伪方式是在两个真实工作区各跑两周，统计打回里结构类与语义类的比例。\n\n| 信息缺口 | 影响哪个结论 | 获取成本 | 处理方式 |\n|---|---|---|---|\n| 只有 2 个团队的样本，跨团队规模效应未验证 | D-1 | 约 3 人日（再访谈 5 个团队） | 下次补；在此之前 D-1 只作为「值得试点」的结论使用 |\n| 探针由规则作者自己构造，可能存在「只测了已知判据」的偏差 | D-1 | 约 1 人日（引入第三方判据清单） | 本次接受不确定性，写明失效条件：出现探针未覆盖的结构判据被误判时复议 |\n| 宿主未来若开放工具入参改写，D-2 的成本对比会变 | D-2 | 无（等待宿主变更） | 下次补；E-1 契约一变即触发复议 |\n| 非 markdown 类型的诉求未调研 | D-1 | 约 2 人日 | 本次明确排除，不纳入结论 |\n\n## 开放问题  serves: 全文\n\n| 问题 | 选项 | 负责人 | 截止 |\n|---|---|---|---|\n| 默认 severity 是否把「无 owner」保留为 error | 保留 error / 降为 warning | 插件组 | 已决：保留 error |\n| 是否需要跨工作区共享判据 | 支持 / 不支持 | 插件组 | 2026-10-30 |\n| 校验结果是否要落审计日志 | 落 / 不落 | 宿主组 | 2026-10-30 |\n| 打回时是否内联示例文档全文 | 内联 / 只给指针 | 插件组 | 已决：小模板内联，超阈值给指针 |\n\n## 附录  serves: 全文\n\n- **访谈与问卷**：3 个项目组 + 2 名评审人，半结构化访谈，逐条原文记录（内部记录，含对象代号）；E-4、E-5 的原始摘录。\n- **实测脚本与原始数据**：4 组探针文档与运行脚本位于临时工作区，复现命令为 `validateDocument(spec, text, null, text, { fileName })`；E-2 的结果含每条违规的 rule id 与行号。\n- **相关文档**：[PRD 示例](../prd/example.md)（本调研的直接下游）、[设计示例](../design/example.md)、路径规则子系统 README。\n- **评审与复议记录**：2026-10-15 内部评审，参与人为插件组 + 架构组；结论为「立项，但 D-1 只作试点结论」，复议触发条件见风险与不确定性。\n- **变更历史**：2026-10-14 初稿（Q-1、Q-2）；2026-10-15 补 Q-4 与信息缺口表；结论未翻转。\n"
  }
}
